window.ETSDATA=window.ETSDATA||{};window.ETSDATA[28]={"lc":{"p1":[{"n":1,"opts":["The woman is setting a table.","The woman is inspecting a machine.","The woman is moving a chair.","The woman is working at a reception desk."],"vi":["Người phụ nữ đang bày bàn ăn.","Người phụ nữ đang kiểm tra một cái máy.","Người phụ nữ đang di chuyển một chiếc ghế.","Người phụ nữ đang làm việc ở quầy lễ tân."],"ans":"D","xp":"Tranh: người phụ nữ đứng sau quầy lễ tân dài → (D). Các động tác bày bàn, kiểm tra máy, dời ghế không có trong tranh.","a":"XC-T08-01.mp3","img":"q1.jpg"},{"n":2,"opts":["They are sitting outside.","They are walking on the trail.","They are parking a car.","They are drinking some tea."],"vi":["Họ đang ngồi ngoài trời.","Họ đang đi bộ trên đường mòn.","Họ đang đỗ xe.","Họ đang uống trà."],"ans":"A","xp":"Tranh: hai người ngồi ghế xếp ngoài trời cạnh xe cắm trại → (A). (B) không đi bộ, (C) xe đã đỗ sẵn, không ai đang đỗ, (D) không uống trà.","a":"XC-T08-02.mp3","img":"q2.jpg"},{"n":3,"opts":["He is turning on a light.","He is putting on an apron.","He is looking into an oven.","He is baking some bread."],"vi":["Anh ấy đang bật đèn.","Anh ấy đang đeo tạp dề.","Anh ấy đang nhìn vào trong lò nướng.","Anh ấy đang nướng bánh mì."],"ans":"C","xp":"Tranh: người đàn ông cúi nhìn vào lò nướng đang mở → (C). (D) không thấy bánh mì; (A)(B) không có động tác này.","a":"XC-T08-03.mp3","img":"q3.jpg"},{"n":4,"opts":["Some people are watching a performance.","Some people are boarding an airplane.","Some people are checking in their luggage.","Some people are standing near a carousel."],"vi":["Một số người đang xem biểu diễn.","Một số người đang lên máy bay.","Một số người đang ký gửi hành lý.","Một số người đang đứng gần băng chuyền hành lý."],"ans":"D","xp":"Tranh: mọi người đứng chờ bên băng chuyền hành lý ở sân bay → (D) carousel = băng chuyền hành lý. (B)(C) liên tưởng sân bay nhưng không đúng hành động.","a":"XC-T08-04.mp3","img":"q4.jpg"},{"n":5,"opts":["One of the men is hanging a painting on a wall.","A bag has been placed on the sofa.","Some people are resting on the floor.","Some documents are spread out on a table."],"vi":["Một người đàn ông đang treo tranh lên tường.","Một chiếc túi được đặt trên ghế sô pha.","Một số người đang nghỉ trên sàn.","Một số tài liệu được trải ra trên bàn."],"ans":"D","xp":"Tranh: nhóm người ngồi quanh bàn có nhiều giấy tờ bày ra → (D). (A) không ai treo tranh, (B) không có túi trên sofa, (C) không ai ngồi sàn.","a":"XC-T08-05.mp3","img":"q5.jpg"},{"n":6,"opts":["Some chairs have been stacked on top of each other.","Some memos are being posted on a board.","A microwave is being cleaned.","Some clocks have been mounted on walls."],"vi":["Một số ghế được xếp chồng lên nhau.","Một số ghi chú đang được dán lên bảng.","Lò vi sóng đang được lau chùi.","Một số đồng hồ được gắn trên tường."],"ans":"D","xp":"Tranh: phòng trống, trên tường có nhiều đồng hồ → (D). (B)(C) dạng 'being + V3' cần có người làm nhưng tranh không có người; (A) ghế không chồng lên nhau.","a":"XC-T08-06.mp3","img":"q6.jpg"}],"p2":[{"n":7,"q":"When did the landlord sign this document?","qvi":"Chủ nhà ký giấy tờ này khi nào?","opts":["A few days ago.","The lease agreement.","He owns three apartments."],"vi":["Vài ngày trước.","Hợp đồng thuê nhà.","Ông ấy sở hữu ba căn hộ."],"ans":"A","xp":"Câu hỏi When → (A) 'Vài ngày trước'. (B)(C) liên tưởng landlord – hợp đồng thuê, căn hộ.","a":"XC-T08-07.mp3"},{"n":8,"q":"Where's the accounting department?","qvi":"Phòng kế toán ở đâu?","opts":["In the east wing.","Eight employees.","A bank account."],"vi":["Ở khu nhà phía đông.","Tám nhân viên.","Một tài khoản ngân hàng."],"ans":"A","xp":"Câu hỏi Where → (A) 'Ở khu phía đông'. (C) lặp âm accounting/account.","a":"XC-T08-08.mp3"},{"n":9,"q":"How often does the mail get picked up from here?","qvi":"Thư ở đây được lấy đi bao lâu một lần?","opts":["Isn't it too heavy?","Express shipping costs extra.","Usually twice a day."],"vi":["Nó có nặng quá không?","Gửi nhanh tốn thêm phí.","Thường hai lần một ngày."],"ans":"C","xp":"Câu hỏi How often (tần suất) → (C) 'Thường hai lần một ngày'. (A) liên tưởng pick up – nặng, (B) liên tưởng mail – gửi hàng.","a":"XC-T08-09.mp3"},{"n":10,"q":"Wasn't Annie planning to apply for a passport?","qvi":"Không phải Annie định xin hộ chiếu sao?","opts":["To the local embassy.","No, I'm staying at home.","Yes, for her overseas trip."],"vi":["Đến đại sứ quán địa phương.","Không, tôi ở nhà.","Vâng, cho chuyến đi nước ngoài của cô ấy."],"ans":"C","xp":"Câu hỏi phủ định Yes/No về Annie → (C) 'Vâng, cho chuyến đi nước ngoài của cô ấy'. (B) sai chủ thể (I), (A) liên tưởng passport – đại sứ quán.","a":"XC-T08-10.mp3"},{"n":11,"q":"Why has this machinery been turned off?","qvi":"Sao máy móc này lại bị tắt?","opts":["Yes, press the power button.","Because it's undergoing an inspection.","Every evening at six."],"vi":["Vâng, hãy bấm nút nguồn.","Vì nó đang được kiểm tra.","Mỗi tối lúc 6 giờ."],"ans":"B","xp":"Câu hỏi Why → (B) 'Vì đang được kiểm tra'. (A) Wh- không trả lời Yes, (C) trả lời When.","a":"XC-T08-11.mp3"},{"n":12,"q":"Should we go forward with the sales pitch or postpone the meeting?","qvi":"Chúng ta nên tiếp tục buổi chào hàng hay hoãn cuộc họp?","opts":["Thomas shared some great ideas.","I know I could use more time.","Yes, our sales have increased."],"vi":["Thomas đã chia sẻ vài ý tưởng hay.","Tôi biết là tôi cần thêm thời gian.","Vâng, doanh số đã tăng."],"ans":"B","xp":"Câu hỏi lựa chọn → (B) 'Tôi cần thêm thời gian' = chọn hoãn. (C) câu hỏi lựa chọn không trả lời Yes, lặp từ sales.","a":"XC-T08-12.mp3"},{"n":13,"q":"Can I make a copy of this handbook?","qvi":"Tôi photo cuốn sổ tay này được không?","opts":["It outlines the company's policies.","I've booked a double room.","Sure, but be careful with the original."],"vi":["Nó trình bày các chính sách của công ty.","Tôi đã đặt phòng đôi.","Được, nhưng hãy cẩn thận với bản gốc."],"ans":"C","xp":"Xin phép → đồng ý kèm lưu ý: (C). (B) lặp âm handbook/booked, (A) mô tả cuốn sổ tay nhưng không trả lời.","a":"XC-T08-13.mp3"},{"n":14,"q":"Has the light in the break room been repaired?","qvi":"Đèn ở phòng nghỉ đã được sửa chưa?","opts":["A cracked bulb.","You deserve a break.","I haven't been in there."],"vi":["Một bóng đèn bị nứt.","Bạn xứng đáng được nghỉ ngơi.","Tôi chưa vào đó."],"ans":"C","xp":"Trả lời gián tiếp 'không biết': (C) 'Tôi chưa vào đó'. (A) liên tưởng đèn, (B) lặp từ break.","a":"XC-T08-14.mp3"},{"n":15,"q":"Whose shift overlaps with the regional manager's visit on Saturday?","qvi":"Ca của ai trùng với chuyến thăm của quản lý khu vực vào thứ Bảy?","opts":["Shift these displays to the right.","We can oversee the staff.","I'm off all weekend."],"vi":["Dời các kệ trưng bày này sang phải.","Chúng tôi có thể giám sát nhân viên.","Tôi nghỉ cả cuối tuần."],"ans":"C","xp":"Câu hỏi Whose → trả lời gián tiếp: (C) 'Tôi nghỉ cả cuối tuần' (không phải ca của tôi). (A) lặp từ shift (nghĩa khác: dời), (B) lặp âm overlaps/oversee.","a":"XC-T08-15.mp3"},{"n":16,"q":"Which microphone would you like set up on the stage?","qvi":"Bạn muốn lắp micro nào trên sân khấu?","opts":["I already booked that show.","The cordless one.","That's probably a good idea."],"vi":["Tôi đã đặt vé buổi diễn đó rồi.","Loại không dây.","Có lẽ đó là ý hay."],"ans":"B","xp":"Câu hỏi Which → chọn một cái: (B) 'Loại không dây'. (A) liên tưởng sân khấu – buổi diễn.","a":"XC-T08-16.mp3"},{"n":17,"q":"Isn't there a vacancy for a computer programmer?","qvi":"Không phải đang có chỗ trống cho lập trình viên sao?","opts":["It's easy enough to set up.","Yes, that's my favorite TV program.","The position was filled."],"vi":["Cái đó lắp đặt khá dễ.","Vâng, đó là chương trình TV tôi thích.","Vị trí đó đã có người rồi."],"ans":"C","xp":"Hỏi còn tuyển không → (C) 'Vị trí đó đã có người'. (B) lặp âm programmer/program.","a":"XC-T08-17.mp3"},{"n":18,"q":"Do you think the logo needs updating, or is it all right as it is?","qvi":"Bạn nghĩ logo cần cập nhật hay để nguyên là ổn?","opts":["You can download it from our Web site.","It will reopen soon after a renovation.","I like the current style."],"vi":["Bạn có thể tải nó từ trang web.","Nó sẽ sớm mở cửa lại sau khi cải tạo.","Tôi thích phong cách hiện tại."],"ans":"C","xp":"Câu hỏi lựa chọn → (C) 'Tôi thích phong cách hiện tại' = để nguyên. (A) liên tưởng updating – download.","a":"XC-T08-18.mp3"},{"n":19,"q":"How high should we set the thermostat?","qvi":"Chúng ta nên chỉnh nhiệt độ cao bao nhiêu?","opts":["Hmm, we'd better ask the building manager.","Yes, it's getting cold in here.","It's near the main stairwell."],"vi":["Hừm, chúng ta nên hỏi quản lý tòa nhà.","Vâng, ở đây đang lạnh dần.","Nó ở gần cầu thang chính."],"ans":"A","xp":"Trả lời gián tiếp 'không biết, hỏi người khác': (A). (B) câu hỏi How không trả lời Yes, (C) trả lời Where.","a":"XC-T08-19.mp3"},{"n":20,"q":"When will the new amusement park open?","qvi":"Khi nào công viên giải trí mới mở cửa?","opts":["Not until the peak season.","Mainly attractions for children.","I found it rather amusing."],"vi":["Phải đến mùa cao điểm.","Chủ yếu là trò chơi cho trẻ em.","Tôi thấy nó khá thú vị."],"ans":"A","xp":"Câu hỏi When → (A) 'Phải đến mùa cao điểm'. (C) lặp âm amusement/amusing.","a":"XC-T08-20.mp3"},{"n":21,"q":"Here's the final draft of the press release.","qvi":"Đây là bản nháp cuối của thông cáo báo chí.","opts":["The deadline for submissions is Friday.","Mr. Brady wants to look it over.","No, the product hasn't been released."],"vi":["Hạn nộp là thứ Sáu.","Ông Brady muốn xem qua nó.","Không, sản phẩm chưa được ra mắt."],"ans":"B","xp":"Đưa bản nháp → (B) 'Ông Brady muốn xem qua' (chuyển cho người duyệt). (C) lặp âm release/released.","a":"XC-T08-21.mp3"},{"n":22,"q":"Should I use a recruitment agency to find the replacement for Ms. Morgan?","qvi":"Tôi có nên dùng công ty tuyển dụng để tìm người thay bà Morgan không?","opts":["She has a lot of experience.","Just place it on my desk.","That would be rather expensive."],"vi":["Bà ấy có nhiều kinh nghiệm.","Cứ để nó trên bàn tôi.","Việc đó sẽ khá tốn kém."],"ans":"C","xp":"Xin ý kiến → (C) 'Như vậy khá tốn kém' (gián tiếp không đồng ý). (B) lặp âm replacement/place.","a":"XC-T08-22.mp3"},{"n":23,"q":"Have you adjusted the sales figures for March?","qvi":"Bạn đã điều chỉnh số liệu bán hàng tháng 3 chưa?","opts":["Please let me know when you figure it out.","The merchandise is on sale.","Yes, according to your notes."],"vi":["Hãy báo tôi khi bạn tìm ra.","Hàng đang giảm giá.","Rồi, theo ghi chú của bạn."],"ans":"C","xp":"Câu hỏi Yes/No → (C) 'Rồi, theo ghi chú của bạn'. (A) lặp âm figures/figure, (B) lặp âm sales/sale.","a":"XC-T08-23.mp3"},{"n":24,"q":"Would you pick up the magazine's new issue at the newsstand?","qvi":"Bạn mua giúp số tạp chí mới ở sạp báo được không?","opts":["If it can wait until my lunch break.","Did you watch the news last night?","Please pick whichever one you like."],"vi":["Nếu đợi được đến giờ nghỉ trưa của tôi.","Tối qua bạn có xem tin tức không?","Cứ chọn cái nào bạn thích."],"ans":"A","xp":"Lời nhờ → đồng ý có điều kiện: (A) 'Nếu đợi được đến giờ nghỉ trưa'. (B) lặp âm newsstand/news, (C) lặp từ pick.","a":"XC-T08-24.mp3"},{"n":25,"q":"Hello, I'm here to apply for a driver's license.","qvi":"Xin chào, tôi đến để xin bằng lái xe.","opts":["Fill out this form completely.","I usually take the bus instead.","We have plenty of supplies."],"vi":["Hãy điền đầy đủ mẫu đơn này.","Tôi thường đi xe buýt.","Chúng tôi có nhiều vật tư."],"ans":"A","xp":"Người đến làm thủ tục → nhân viên hướng dẫn: (A) 'Hãy điền đầy đủ mẫu đơn này'. (B) liên tưởng lái xe – xe buýt.","a":"XC-T08-25.mp3"},{"n":26,"q":"Where are the blueprints for the new apartment building?","qvi":"Bản thiết kế tòa chung cư mới ở đâu?","opts":["Didn't Nicolas review them?","No later than September.","Yes, with spacious rooms."],"vi":["Không phải Nicolas đã xem chúng sao?","Không muộn hơn tháng 9.","Vâng, với các phòng rộng rãi."],"ans":"A","xp":"Câu hỏi Where → trả lời gián tiếp: (A) 'Không phải Nicolas đã xem chúng sao?' (chắc ở chỗ Nicolas). (B) trả lời When, (C) Wh- không trả lời Yes.","a":"XC-T08-26.mp3"},{"n":27,"q":"Why don't I put these confidential files in a locked cabinet?","qvi":"Hay là tôi cất những hồ sơ mật này vào tủ khóa nhé?","opts":["The door should remain closed.","I'm confident in her abilities.","I would appreciate that."],"vi":["Cửa nên luôn đóng.","Tôi tin vào năng lực của cô ấy.","Vậy thì tốt quá."],"ans":"C","xp":"'Why don't I...?' là lời đề nghị giúp → (C) 'Vậy thì tốt quá/cảm ơn'. (B) lặp âm confidential/confident, (A) liên tưởng khóa – cửa.","a":"XC-T08-27.mp3"},{"n":28,"q":"You worked overtime yesterday evening, didn't you?","qvi":"Tối qua bạn làm thêm giờ phải không?","opts":["No, I had a family gathering.","Mr. Ellis has worked here for over ten years.","It's later than I expected."],"vi":["Không, tôi có buổi họp mặt gia đình.","Ông Ellis đã làm ở đây hơn mười năm.","Muộn hơn tôi nghĩ."],"ans":"A","xp":"Câu hỏi đuôi → (A) 'Không, tôi có buổi họp mặt gia đình'. (B) lặp từ worked, (C) liên tưởng overtime – muộn.","a":"XC-T08-28.mp3"},{"n":29,"q":"Where can I get the best view of the Independence Day Parade?","qvi":"Tôi xem diễu hành Ngày Độc lập ở đâu rõ nhất?","opts":["Probably on Main Street.","It's held every year.","To celebrate the holiday."],"vi":["Có lẽ là trên phố Main.","Nó được tổ chức hằng năm.","Để mừng ngày lễ."],"ans":"A","xp":"Câu hỏi Where → (A) 'Có lẽ là trên phố Main'. (B)(C) liên tưởng diễu hành.","a":"XC-T08-29.mp3"},{"n":30,"q":"Have you seen the comments about that restaurant?","qvi":"Bạn đã xem các bình luận về nhà hàng đó chưa?","opts":["He'll meet you at the entrance.","All right, we should avoid it.","I'm not feeling hungry."],"vi":["Anh ấy sẽ gặp bạn ở lối vào.","Được rồi, chúng ta nên tránh nó.","Tôi không thấy đói."],"ans":"B","xp":"Ngụ ý bình luận xấu → (B) 'Được rồi, vậy nên tránh nhà hàng đó'. (C) liên tưởng nhà hàng – đói.","a":"XC-T08-30.mp3"},{"n":31,"q":"The customer service questionnaire contains an error.","qvi":"Bảng câu hỏi về dịch vụ khách hàng có một lỗi.","opts":["We should tell Barry about it.","Overall, we're happy with the scores.","To get more reliable feedback."],"vi":["Chúng ta nên báo Barry.","Nhìn chung chúng tôi hài lòng với điểm số.","Để có phản hồi đáng tin hơn."],"ans":"A","xp":"Báo có lỗi → đưa hướng xử lý: (A) 'Nên báo Barry'. (B)(C) liên tưởng khảo sát.","a":"XC-T08-31.mp3"}],"p3":[{"ns":[32,34],"script":[["W","Good afternoon. I brought my phone in this morning because it had a cracked screen. It was supposed to be fixed by four o'clock. My name is Monica Rogers.","Chào buổi chiều. Sáng nay tôi mang điện thoại đến vì màn hình bị nứt. Lẽ ra nó được sửa xong trước 4 giờ. Tôi tên là Monica Rogers."],["M","I'm sorry, Ms. Rogers, but your phone isn't ready yet. We've fallen behind because one of our staff members called in sick today, so we only have two people working. Would you be able to come back tomorrow?","Xin lỗi chị Rogers, điện thoại của chị chưa xong. Chúng tôi bị chậm vì hôm nay một nhân viên gọi báo ốm, nên chỉ có hai người làm. Chị có thể quay lại ngày mai không?"],["W","Well, I'm taking a long train ride this evening, and I need to have my phone with me.","À, tối nay tôi đi tàu đường dài và tôi cần mang điện thoại theo."],["M","I understand. There are a few orders ahead of yours, but I'll do yours first. If you stop back in half an hour, it'll be ready.","Tôi hiểu. Có vài đơn trước chị, nhưng tôi sẽ làm của chị trước. Nửa tiếng nữa chị quay lại là xong."]],"qs":[{"n":32,"q":"Where most likely are the speakers?","qvi":"Những người nói nhiều khả năng đang ở đâu?","opts":["At a café","At a repair shop","At a warehouse","At a train station"],"vi":["Ở quán cà phê","Ở tiệm sửa chữa","Ở nhà kho","Ở ga tàu"],"ans":"B","xp":"'I brought my phone in this morning because it had a cracked screen. It was supposed to be fixed' → tiệm sửa điện thoại → (B). (D) liên tưởng 'train ride'."},{"n":33,"q":"According to the man, what has caused a delay?","qvi":"Theo người đàn ông, điều gì gây chậm trễ?","opts":["An order form was lost.","A machine has broken down.","A shipment has not arrived.","An employee is absent."],"vi":["Mất phiếu đặt hàng.","Máy bị hỏng.","Hàng chưa về.","Một nhân viên vắng mặt."],"ans":"D","xp":"'one of our staff members called in sick today' → nhân viên nghỉ → (D)."},{"n":34,"q":"What does the man say he will do?","qvi":"Người đàn ông nói sẽ làm gì?","opts":["Send an item by express mail","Give the woman a discount","Order some new components","Change the order of some tasks"],"vi":["Gửi đồ bằng chuyển phát nhanh","Giảm giá cho người phụ nữ","Đặt linh kiện mới","Đổi thứ tự công việc"],"ans":"D","xp":"'There are a few orders ahead of yours, but I'll do yours first' → ưu tiên làm trước = đổi thứ tự → (D)."}],"a":"XC-T08-32-34.mp3"},{"ns":[35,37],"script":[["W","Hello. This is Sharon Tate. I reserved a vehicle to be picked up next week at your Rockford location.","Xin chào, tôi là Sharon Tate. Tôi đã đặt một chiếc xe để nhận vào tuần sau ở chi nhánh Rockford."],["M","Good morning, Ms. Tate. I see here that you reserved a compact car for three days.","Chào buổi sáng chị Tate. Tôi thấy chị đã đặt một xe cỡ nhỏ trong ba ngày."],["W","Well, that's the problem. I got the confirmation e-mail, but it said I'm returning the car on June 8th. It should be June 9th.","Vấn đề là ở đó. Tôi nhận e-mail xác nhận, nhưng ghi là tôi trả xe ngày 8 tháng 6. Lẽ ra phải là ngày 9."],["M","Oh, I'm sorry about that. I'll change it on our computer right away and send you a new e-mail. And by way of apology, I'll add our roadside assistance service at no cost.","Ồ, tôi xin lỗi. Tôi sẽ sửa ngay trên máy và gửi e-mail mới cho chị. Và để xin lỗi, tôi sẽ thêm dịch vụ cứu hộ trên đường miễn phí."]],"qs":[{"n":35,"q":"Where does the man work?","qvi":"Người đàn ông làm việc ở đâu?","opts":["At a commercial airline","At a restaurant","At a car rental agency","At a hotel"],"vi":["Ở hãng hàng không","Ở nhà hàng","Ở công ty cho thuê xe","Ở khách sạn"],"ans":"C","xp":"'I reserved a vehicle to be picked up... returning the car' → công ty cho thuê xe → (C)."},{"n":36,"q":"What problem does the woman tell the man about?","qvi":"Người phụ nữ báo vấn đề gì?","opts":["Her confirmation e-mail did not arrive.","Her bill was more than expected.","Her personal items were damaged.","Her reservation was incorrect."],"vi":["Không nhận được e-mail xác nhận.","Hóa đơn cao hơn dự kiến.","Đồ cá nhân bị hư.","Thông tin đặt chỗ bị sai."],"ans":"D","xp":"'it said I'm returning the car on June 8th. It should be June 9th' → đặt chỗ ghi sai → (D). (A) sai: cô có nhận e-mail."},{"n":37,"q":"What does the man offer to do?","qvi":"Người đàn ông đề nghị làm gì?","opts":["Call the woman back","Talk to a manager","Send a refund","Add a free service"],"vi":["Gọi lại cho cô","Nói chuyện với quản lý","Hoàn tiền","Thêm một dịch vụ miễn phí"],"ans":"D","xp":"'I'll add our roadside assistance service at no cost' → thêm dịch vụ miễn phí → (D)."}],"a":"XC-T08-35-37.mp3"},{"ns":[38,40],"script":[["M","Marjorie, I have a customer who is trying to send a parcel by Express Mail. However, the computer says the charge is $49.99 because the box is over five pounds. But it should be a flat rate of $24.99 regardless of the weight.","Marjorie, tôi có một khách muốn gửi bưu kiện bằng thư chuyển phát nhanh. Nhưng máy tính báo phí là 49,99 đô la vì thùng nặng hơn 5 pound. Lẽ ra phải là giá cố định 24,99 đô la bất kể trọng lượng."],["W","That's what I thought.","Tôi cũng nghĩ vậy."],["M","There's no way to change the price in the system, is there?","Không có cách nào sửa giá trong hệ thống phải không?"],["W","No, but you can just type in the weight yourself instead of using the scale's reading. Set the weight to two pounds, and then the right price should come up.","Không, nhưng anh có thể tự gõ trọng lượng thay vì dùng số đo của cân. Đặt trọng lượng là 2 pound, giá đúng sẽ hiện ra."]],"qs":[{"n":38,"q":"Where do the speakers most likely work?","qvi":"Họ nhiều khả năng làm việc ở đâu?","opts":["At a post office","At a library","At a clothing shop","At a bank"],"vi":["Ở bưu điện","Ở thư viện","Ở cửa hàng quần áo","Ở ngân hàng"],"ans":"A","xp":"'a customer who is trying to send a parcel by Express Mail' → bưu điện → (A)."},{"n":39,"q":"What problem is being discussed?","qvi":"Vấn đề nào đang được bàn?","opts":["A computer shutdown","A broken item","A system error","An outdated policy"],"vi":["Máy tính tắt","Đồ bị vỡ","Lỗi hệ thống","Chính sách lỗi thời"],"ans":"C","xp":"'the computer says the charge is $49.99... But it should be a flat rate of $24.99' → hệ thống tính sai → (C)."},{"n":40,"q":"What does the woman suggest doing?","qvi":"Người phụ nữ đề xuất làm gì?","opts":["Reading a device's user guide","Inputting some information manually","Asking a customer to return later","Moving to a different computer"],"vi":["Đọc hướng dẫn thiết bị","Nhập thông tin thủ công","Bảo khách quay lại sau","Chuyển sang máy tính khác"],"ans":"B","xp":"'you can just type in the weight yourself instead of using the scale's reading' → nhập thủ công → (B)."}],"a":"XC-T08-38-40.mp3"},{"ns":[41,43],"script":[["W1","Mr. Castillo, today I'd like to talk about the preparations you need before moving into the new building. I've invited Crystal Dana, the interior designer, to join us.","Ông Castillo, hôm nay tôi muốn bàn về những việc cần chuẩn bị trước khi chuyển vào tòa nhà mới. Tôi đã mời Crystal Dana, nhà thiết kế nội thất, cùng tham gia."],["M","Thank you both for making time to meet with me. My business recently downsized, so I wanted to move to a smaller building.","Cảm ơn hai chị đã dành thời gian gặp tôi. Công ty tôi vừa thu hẹp quy mô nên tôi muốn chuyển sang tòa nhà nhỏ hơn."],["W2","That's understandable. Now, you said you want to focus the majority of the decorating budget on the waiting room, right?","Điều đó dễ hiểu. Ông nói muốn dành phần lớn ngân sách trang trí cho phòng chờ, đúng không?"],["M","Yes, it's the first thing customers see when they visit.","Đúng vậy, đó là nơi đầu tiên khách nhìn thấy khi đến."],["W2","No problem. I will prepare some color samples for you to choose from.","Không vấn đề gì. Tôi sẽ chuẩn bị vài mẫu màu để ông chọn."],["M","Perfect! And I just want to make sure everything will be done by the March 10 deadline. We've already promoted our grand opening at the new site.","Tuyệt! Và tôi chỉ muốn chắc rằng mọi thứ sẽ xong trước hạn chót ngày 10 tháng 3. Chúng tôi đã quảng bá lễ khai trương ở địa điểm mới rồi."]],"qs":[{"n":41,"q":"According to the man, why will the business relocate?","qvi":"Theo người đàn ông, vì sao công ty chuyển chỗ?","opts":["The neighborhood is too far away.","The rental fee has gone up.","The employees need a meeting space.","The staff size has decreased."],"vi":["Khu vực quá xa.","Tiền thuê tăng.","Nhân viên cần chỗ họp.","Số nhân viên đã giảm."],"ans":"D","xp":"'My business recently downsized, so I wanted to move to a smaller building' → quy mô nhân sự giảm → (D)."},{"n":42,"q":"On which part of the new building will the most money be spent?","qvi":"Phần nào của tòa nhà mới sẽ tốn nhiều tiền nhất?","opts":["A waiting area","A conference room","A staff lounge","An executive's office"],"vi":["Khu chờ","Phòng họp","Phòng nghỉ nhân viên","Văn phòng giám đốc"],"ans":"A","xp":"'focus the majority of the decorating budget on the waiting room' → (A)."},{"n":43,"q":"According to the man, why must work be completed on time?","qvi":"Theo người đàn ông, vì sao công việc phải xong đúng hạn?","opts":["A crew has other projects.","A room was already booked for an event.","A budget is limited.","A change has been advertised."],"vi":["Đội thợ có dự án khác.","Phòng đã được đặt cho sự kiện.","Ngân sách có hạn.","Một thay đổi đã được quảng bá."],"ans":"D","xp":"'We've already promoted our grand opening at the new site' → việc chuyển địa điểm đã được quảng bá → (D)."}],"a":"XC-T08-41-43.mp3"},{"ns":[44,46],"script":[["W","I've just compiled the sales figures for our store, and the numbers for our sofas and dining room sets are down compared to previous months.","Tôi vừa tổng hợp số liệu bán hàng của cửa hàng, doanh số sô pha và bộ bàn ăn đều giảm so với các tháng trước."],["M","That's not surprising. Ever since Bradley's opened across the street, people don't want to spend much time in our store.","Không có gì lạ. Từ khi Bradley's mở cửa bên kia đường, khách không muốn ở lâu trong cửa hàng mình."],["W","You're right. It seems they're just stopping by for a quick check before heading over to the new shop. We've got to do something about this.","Anh nói đúng. Có vẻ họ chỉ ghé xem nhanh rồi sang cửa hàng mới. Mình phải làm gì đó."],["M","Hmm... we don't have space to offer a wider selection, but we could put more ads online and in the newspaper.","Hừm... mình không có chỗ để bày thêm nhiều mẫu, nhưng có thể quảng cáo nhiều hơn trên mạng và trên báo."],["W","That might work. People need to be reminded of the high-quality goods we offer.","Có thể hiệu quả đấy. Cần nhắc mọi người về hàng chất lượng cao của mình."]],"qs":[{"n":44,"q":"What kind of business do the speakers probably work for?","qvi":"Họ nhiều khả năng làm cho loại doanh nghiệp nào?","opts":["An accounting firm","A moving company","A real estate agency","A furniture store"],"vi":["Công ty kế toán","Công ty chuyển nhà","Công ty bất động sản","Cửa hàng nội thất"],"ans":"D","xp":"'the numbers for our sofas and dining room sets are down' → cửa hàng nội thất → (D)."},{"n":45,"q":"What has created a problem for the business?","qvi":"Điều gì gây khó khăn cho cửa hàng?","opts":["Some employees have a schedule conflict.","A competitor has opened nearby.","Some customers made complaints.","Some devices are not working properly."],"vi":["Nhân viên trùng lịch.","Đối thủ mở cửa gần đó.","Khách phàn nàn.","Thiết bị trục trặc."],"ans":"B","xp":"'Ever since Bradley's opened across the street' → đối thủ mở gần đó → (B)."},{"n":46,"q":"What do the speakers plan to do?","qvi":"Họ định làm gì?","opts":["Increase their advertising","Hold a training session","Create an online account","Offer a wider range of options"],"vi":["Tăng quảng cáo","Tổ chức đào tạo","Tạo tài khoản trực tuyến","Bày thêm nhiều lựa chọn"],"ans":"A","xp":"'we could put more ads online and in the newspaper' – 'That might work' → tăng quảng cáo → (A). (D) không có chỗ để bày thêm."}],"a":"XC-T08-44-46.mp3"},{"ns":[47,49],"script":[["M","I'm trying to print out some staff manuals for the new employees, but nothing is coming out. Any ideas?","Tôi đang in sổ tay nhân viên cho người mới mà máy không ra gì cả. Có ai biết sao không?"],["W1","I don't have time to take a look at the printer now, but you could just use the one in the marketing department. I'm sure they wouldn't mind.","Giờ tôi không có thời gian xem máy in, nhưng anh có thể dùng máy ở phòng marketing. Chắc họ không phiền đâu."],["M","Actually, that's not a good idea. I think the marketing team is hosting some visitors, so...","Thật ra không nên. Tôi nghĩ nhóm marketing đang tiếp khách, nên..."],["W1","Oh, thanks for letting me know. I don't want to disturb them.","Ồ, cảm ơn đã báo. Tôi không muốn làm phiền họ."],["W2","You know, it might just be an empty ink cartridge. Vincent in IT probably has some extra ones. Angela, will you call him to bring one?","Có khi chỉ là hết mực thôi. Vincent ở phòng IT chắc có hộp mực dự phòng. Angela, chị gọi anh ấy mang một hộp đến nhé?"],["W1","Sure. And if you still have the problem with a new one, just let me know.","Được. Và nếu thay hộp mới mà vẫn lỗi thì cứ báo tôi."]],"qs":[{"n":47,"q":"What is the man trying to do?","qvi":"Người đàn ông đang cố làm gì?","opts":["Rearrange a team","Print some documents","Schedule a meeting","Research some data"],"vi":["Sắp xếp lại nhóm","In tài liệu","Lên lịch họp","Nghiên cứu dữ liệu"],"ans":"B","xp":"'I'm trying to print out some staff manuals' → in tài liệu → (B)."},{"n":48,"q":"What does the man mean when he says, \"I think the marketing team is hosting some visitors\"?","qvi":"Người đàn ông có ý gì khi nói \"tôi nghĩ nhóm marketing đang tiếp khách\"?","opts":["He has more copies for them.","He needs to find a larger room.","His team is now understaffed.","He doesn't want to interrupt a meeting."],"vi":["Ông có thêm bản in cho họ.","Ông cần phòng rộng hơn.","Nhóm ông thiếu người.","Ông không muốn làm gián đoạn cuộc gặp."],"ans":"D","xp":"Được gợi ý dùng máy in phòng marketing, ông nói 'that's not a good idea' vì họ đang tiếp khách → không muốn làm phiền cuộc gặp → (D)."},{"n":49,"q":"What will Angela probably do next?","qvi":"Angela nhiều khả năng sẽ làm gì tiếp theo?","opts":["Contact a business","Speak to a colleague","Check some figures","Place a supply order"],"vi":["Liên hệ một công ty","Nói chuyện với đồng nghiệp","Kiểm tra số liệu","Đặt mua vật tư"],"ans":"B","xp":"'Angela, will you call him (Vincent in IT) to bring one?' – 'Sure' → gọi cho đồng nghiệp → (B)."}],"a":"XC-T08-47-49.mp3"},{"ns":[50,52],"script":[["M","You've organized a lot of company activities, haven't you, Rebecca?","Chị đã tổ chức nhiều hoạt động của công ty rồi phải không, Rebecca?"],["W","Yes, at least a few major events a year. Why?","Đúng, mỗi năm ít nhất vài sự kiện lớn. Sao vậy?"],["M","I'm in charge of the year-end banquet for our branch, and I'm having trouble deciding which venue to choose. Is there one in particular that you would recommend?","Tôi phụ trách tiệc tất niên của chi nhánh và đang khó chọn địa điểm. Chị có gợi ý chỗ nào không?"],["W","Hmm... Russell Plaza has reasonable prices, and they offer an on-site catering service. Their parking lot is very small, though. There are only about 25 spots, which is never enough.","Hừm... Russell Plaza giá hợp lý và có dịch vụ ăn uống tại chỗ. Nhưng bãi đỗ xe rất nhỏ. Chỉ có khoảng 25 chỗ, không bao giờ đủ."],["M","That shouldn't be an issue, since most people will take public transportation. I guess I'll arrange a tour of the site to make sure it's okay before I commit to it. I'll take care of that now.","Chuyện đó không sao vì hầu hết mọi người sẽ đi phương tiện công cộng. Chắc tôi sẽ sắp xếp đi xem địa điểm cho chắc trước khi chốt. Tôi làm việc đó ngay bây giờ."]],"qs":[{"n":50,"q":"Why does the man ask for the woman's advice?","qvi":"Vì sao người đàn ông hỏi ý kiến người phụ nữ?","opts":["He is finding a new supplier.","He recently moved to a new neighborhood.","He is planning a company event.","He is behind schedule on a work assignment."],"vi":["Đang tìm nhà cung cấp mới.","Vừa chuyển nhà.","Đang lên kế hoạch sự kiện công ty.","Bị chậm tiến độ công việc."],"ans":"C","xp":"'I'm in charge of the year-end banquet for our branch... which venue to choose' → lên kế hoạch sự kiện công ty → (C)."},{"n":51,"q":"What does the woman mention about parking at Russell Plaza?","qvi":"Người phụ nữ nói gì về bãi đỗ xe ở Russell Plaza?","opts":["It is extremely limited.","Its costs can be reimbursed.","It has become more expensive.","It is monitored by guards."],"vi":["Rất hạn chế.","Được hoàn phí.","Đắt hơn trước.","Có bảo vệ trông."],"ans":"A","xp":"'Their parking lot is very small... only about 25 spots, which is never enough' → (A)."},{"n":52,"q":"What will the man probably do next?","qvi":"Người đàn ông nhiều khả năng sẽ làm gì tiếp theo?","opts":["Arrange transportation","Sign a contract","Book a tour","Visit a site"],"vi":["Sắp xếp phương tiện đi lại","Ký hợp đồng","Đặt lịch tham quan","Đến xem địa điểm"],"ans":"C","xp":"'I'll arrange a tour of the site... I'll take care of that now' → đặt lịch tham quan → (C). (D) là việc sau đó, chưa phải ngay bây giờ."}],"a":"XC-T08-50-52.mp3"},{"ns":[53,55],"script":[["M","Hi, Marilyn. I'm glad I caught you before you went to your meeting with Ms. Patel. Can you talk about the catalog for a minute or two?","Chào Marilyn. May mà gặp được chị trước khi chị đi họp với bà Patel. Chị có thể nói chuyện về danh mục sản phẩm một hai phút không?"],["W","Umm... yes, but no more than that. I don't want to be late.","Ừm... được, nhưng không lâu hơn đâu. Tôi không muốn bị muộn."],["M","Okay, well, I was looking at the draft that is supposed to be sent to the printer this afternoon. I think the photographs will be an issue. They're just too small to allow customers to see the details of the products easily.","Được, tôi đang xem bản nháp sẽ gửi đi in chiều nay. Tôi nghĩ ảnh sẽ là vấn đề. Chúng quá nhỏ, khách khó thấy rõ chi tiết sản phẩm."],["W","Actually, I only worked on the text. Alex was assigned the layout work.","Thật ra tôi chỉ phụ trách phần chữ. Alex được giao phần dàn trang."],["M","I'm sorry about that. I thought it was you. Then I'll talk to Alex instead.","Xin lỗi chị. Tôi tưởng là chị. Vậy tôi sẽ nói với Alex."]],"qs":[{"n":53,"q":"What does the woman suggest when she says, \"but no more than that\"?","qvi":"Người phụ nữ ngụ ý gì khi nói \"nhưng không lâu hơn đâu\"?","opts":["She wants a meeting to be small.","She will approve the budget.","She thinks a catalog should be shortened.","She has a limited amount of time."],"vi":["Muốn cuộc họp nhỏ.","Sẽ duyệt ngân sách.","Nghĩ danh mục nên rút ngắn.","Có ít thời gian."],"ans":"D","xp":"Ông hỏi nói chuyện 'a minute or two'; bà đáp 'no more than that. I don't want to be late' → bà có ít thời gian → (D)."},{"n":54,"q":"What concern does the man tell the woman about?","qvi":"Người đàn ông nêu băn khoăn gì?","opts":["The size of some images","The status of a mailing list","The quality of some paper","The color of some photographs"],"vi":["Kích thước hình ảnh","Tình trạng danh sách gửi thư","Chất lượng giấy","Màu sắc ảnh"],"ans":"A","xp":"'the photographs... They're just too small' → kích thước ảnh → (A)."},{"n":55,"q":"Why does the man make an apology?","qvi":"Vì sao người đàn ông xin lỗi?","opts":["He failed to reach a team goal.","He was confused about assigned tasks.","He is unable to cover a coworker's shift.","He forgot to submit some documents."],"vi":["Không đạt mục tiêu nhóm.","Nhầm lẫn về việc được giao.","Không thể làm thay ca đồng nghiệp.","Quên nộp tài liệu."],"ans":"B","xp":"Bà nói chỉ làm phần chữ, dàn trang là việc của người khác; ông xin lỗi 'I thought it was you' → nhầm người phụ trách → (B)."}],"a":"XC-T08-53-55.mp3"},{"ns":[56,58],"script":[["M","Hello, Ms. Parsons? This is Connor from the head office. I got a message from your supervisor saying that you wanted to move to the office in Toronto.","Alô, chị Parsons phải không? Tôi là Connor ở trụ sở chính. Tôi nhận tin nhắn từ cấp trên của chị nói chị muốn chuyển đến văn phòng ở Toronto."],["W","Yes, that's right. I'm ready for the challenge of working in a larger city.","Vâng, đúng vậy. Tôi sẵn sàng cho thử thách làm việc ở thành phố lớn hơn."],["M","Well, then I have great news for you. We have an opening there for a sales representative. Could you start by the end of the month?","Vậy tôi có tin vui cho chị. Ở đó đang trống vị trí đại diện bán hàng. Chị có thể bắt đầu trước cuối tháng không?"],["W","Well, I'm unfamiliar with the neighborhoods in Toronto, so I'm not sure that would be enough time to find an apartment.","À, tôi không rành các khu ở Toronto, nên không chắc có đủ thời gian tìm căn hộ."],["M","You don't have to worry about that. We have a special service to help you find a place to live and get settled.","Chị không cần lo chuyện đó. Chúng tôi có dịch vụ riêng giúp chị tìm chỗ ở và ổn định."]],"qs":[{"n":56,"q":"What is the conversation mainly about?","qvi":"Cuộc hội thoại chủ yếu nói về điều gì?","opts":["Attending an industry event","Preparing for a promotional event","Implementing a new policy","Transferring to another branch"],"vi":["Dự sự kiện ngành","Chuẩn bị sự kiện quảng bá","Áp dụng chính sách mới","Chuyển sang chi nhánh khác"],"ans":"D","xp":"'you wanted to move to the office in Toronto' và cả bài bàn về việc chuyển đến đó → (D)."},{"n":57,"q":"According to the woman, what could cause a problem?","qvi":"Theo người phụ nữ, điều gì có thể gây khó khăn?","opts":["Her current salary is too low.","Her lease does not expire soon.","She doesn't know an area well.","She is unqualified for a position."],"vi":["Lương hiện tại quá thấp.","Hợp đồng thuê nhà chưa hết hạn.","Không rành một khu vực.","Không đủ năng lực cho vị trí."],"ans":"C","xp":"'I'm unfamiliar with the neighborhoods in Toronto' → không rành khu vực → (C)."},{"n":58,"q":"What does the man tell the woman about?","qvi":"Người đàn ông cho người phụ nữ biết về điều gì?","opts":["A service for locating a home","A new employment agency","A deadline for an application","A special pricing discount"],"vi":["Dịch vụ tìm nhà","Công ty việc làm mới","Hạn nộp hồ sơ","Giảm giá đặc biệt"],"ans":"A","xp":"'We have a special service to help you find a place to live' → dịch vụ tìm nhà → (A)."}],"a":"XC-T08-56-58.mp3"},{"ns":[59,61],"script":[["M","Corina, I've been looking over the schedule you prepared for Ted Jackson's upcoming book tour. I see that you've scheduled an event in Summerville. That's a town of just 12,000 people. We usually focus on big cities, so I'm wondering why Summerville is on the list.","Corina, tôi đang xem lịch trình chị lập cho tour giới thiệu sách sắp tới của Ted Jackson. Tôi thấy chị xếp một sự kiện ở Summerville. Đó là thị trấn chỉ có 12.000 dân. Mình thường tập trung vào thành phố lớn, nên tôi thắc mắc vì sao có Summerville."],["W","It's Ted's hometown, so he'll get a lot of support there. I asked Yolanda in accounting to review the plan. She said that since Ted will be staying with family members, the stop won't cost us much.","Đó là quê của Ted, nên anh ấy sẽ được ủng hộ nhiều. Tôi đã nhờ Yolanda ở phòng kế toán xem kế hoạch. Cô ấy nói vì Ted sẽ ở nhà người thân nên điểm dừng này không tốn mấy."],["M","I see. I guess it's good to have a personal touch, and we can use this to our advantage. I'll get a statement ready for the media next week to highlight the family angle.","Tôi hiểu rồi. Có yếu tố cá nhân cũng hay, và mình có thể tận dụng. Tuần sau tôi sẽ chuẩn bị thông cáo cho báo chí để nhấn mạnh khía cạnh gia đình."]],"qs":[{"n":59,"q":"What does the man want to know about the book tour?","qvi":"Người đàn ông muốn biết gì về tour sách?","opts":["How it will be advertised to the public","Why a small community was included","How many books are likely to be sold","Why it will start later than planned"],"vi":["Sẽ quảng bá thế nào","Vì sao có một thị trấn nhỏ","Sẽ bán được bao nhiêu sách","Vì sao bắt đầu muộn hơn"],"ans":"B","xp":"'That's a town of just 12,000 people... I'm wondering why Summerville is on the list' → (B)."},{"n":60,"q":"Who most likely is Yolanda?","qvi":"Yolanda nhiều khả năng là ai?","opts":["An author","A graphic designer","An accountant","A bookstore owner"],"vi":["Tác giả","Nhà thiết kế đồ họa","Kế toán","Chủ hiệu sách"],"ans":"C","xp":"'Yolanda in accounting' → kế toán → (C)."},{"n":61,"q":"What does the man plan to prepare next week?","qvi":"Tuần sau người đàn ông định chuẩn bị gì?","opts":["A book cover's design","An updated contract","A press release","A ticket for a tour"],"vi":["Thiết kế bìa sách","Hợp đồng cập nhật","Thông cáo báo chí","Vé cho tour"],"ans":"C","xp":"'I'll get a statement ready for the media next week' → thông cáo báo chí → (C)."}],"a":"XC-T08-59-61.mp3"},{"ns":[62,64],"script":[["W","Good morning, and thank you for visiting the Charleston Aquarium.","Chào buổi sáng, cảm ơn anh đã đến Thủy cung Charleston."],["M","Hello. I'd like one standard adult ticket, please. I've read a lot of positive reviews, so I'm looking forward to seeing your site.","Xin chào. Cho tôi một vé người lớn thường. Tôi đọc nhiều đánh giá tốt nên rất mong được tham quan."],["W","Wonderful! Here's your ticket, and the charge is $18.","Tuyệt! Đây là vé của anh, giá 18 đô la."],["M","That's less than I expected. Oh, I've just seen your sign.","Rẻ hơn tôi nghĩ. À, tôi vừa thấy bảng giá của các chị."],["W","The admission includes a free audio tour, so here are the headphones and the player. If you listen to the first five minutes, it'll give you some background information about our facility.","Vé vào cửa có kèm thuyết minh âm thanh miễn phí, đây là tai nghe và máy phát. Anh nghe năm phút đầu sẽ biết thông tin cơ bản về thủy cung."],["M","Oh, thanks. I'll do that now.","Ồ, cảm ơn. Tôi sẽ nghe ngay."],["W","Enjoy your visit!","Chúc anh tham quan vui vẻ!"]],"qs":[{"n":62,"q":"Where are the speakers?","qvi":"Những người nói đang ở đâu?","opts":["At an art gallery","At a performance hall","At a historical home","At an aquarium"],"vi":["Ở phòng tranh","Ở nhà hát","Ở nhà cổ","Ở thủy cung"],"ans":"D","xp":"'thank you for visiting the Charleston Aquarium' → (D)."},{"n":63,"q":"Look at the graphic. Why is the man eligible for a discount?","qvi":"Nhìn hình. Vì sao người đàn ông được giảm giá?","opts":["He has a membership.","He is part of a large group.","It is a Tuesday.","It is near closing time."],"vi":["Ông có thẻ hội viên.","Ông đi theo đoàn đông.","Hôm đó là thứ Ba.","Gần giờ đóng cửa."],"ans":"C","xp":"Ông mua vé người lớn thường, trả '$18'; bảng: Standard Ticket $20.00 ($18.00 on Tuesdays) → hôm đó là thứ Ba → (C)."},{"n":64,"q":"What will the man most likely do next?","qvi":"Người đàn ông nhiều khả năng sẽ làm gì tiếp theo?","opts":["Check a map","Listen to a recording","Attend a lecture","Read a brochure"],"vi":["Xem bản đồ","Nghe bản ghi âm","Dự bài giảng","Đọc tờ giới thiệu"],"ans":"B","xp":"'If you listen to the first five minutes...' – 'I'll do that now' → nghe bản thuyết minh → (B)."}],"a":"XC-T08-62-64.mp3","img":"g62.png"},{"ns":[65,67],"script":[["M","Thanks for having lunch with me, Cheryl. I'm sure you're busy with work these days.","Cảm ơn chị đã đi ăn trưa với tôi, Cheryl. Chắc dạo này chị bận lắm."],["W","I am, but I'm actually thinking about changing jobs. Everyone I currently work with is very friendly. However, the long commute is exhausting. Since I can do graphic design work from anywhere, I'm looking for a job that allows me to work from home.","Đúng vậy, nhưng thật ra tôi đang tính đổi việc. Đồng nghiệp hiện tại ai cũng rất thân thiện. Có điều đi làm xa mệt quá. Vì làm thiết kế đồ họa ở đâu cũng được, tôi đang tìm việc cho phép làm ở nhà."],["M","Have you tried jobdiscovery.net? It has a lot of jobs for graphic designers.","Chị thử jobdiscovery.net chưa? Trên đó có nhiều việc cho nhà thiết kế đồ họa."],["W","I'll be sure to check that out. Thanks. And how's work going for you?","Tôi nhất định sẽ xem. Cảm ơn anh. Còn công việc của anh thế nào?"],["M","There's an opening for a department head that I'm thinking about applying for. It'd be a big step up, though, so I'm nervous about it.","Đang có vị trí trưởng phòng trống mà tôi định ứng tuyển. Đó sẽ là bước tiến lớn nên tôi hơi hồi hộp."]],"qs":[{"n":65,"q":"What benefit of her current job does the woman mention?","qvi":"Người phụ nữ nhắc đến ưu điểm nào của công việc hiện tại?","opts":["She has a variety of projects.","She receives overtime pay.","Her coworkers are friendly.","Her skills are improving steadily."],"vi":["Có nhiều dự án đa dạng.","Được trả lương làm thêm.","Đồng nghiệp thân thiện.","Kỹ năng tiến bộ đều."],"ans":"C","xp":"'Everyone I currently work with is very friendly' → (C)."},{"n":66,"q":"Look at the graphic. Which company will the woman most likely apply to?","qvi":"Nhìn hình. Người phụ nữ nhiều khả năng sẽ ứng tuyển công ty nào?","opts":["Adkins Co.","Delacruz","Pearl, Inc.","Talala"],"vi":["Adkins Co.","Delacruz","Pearl, Inc.","Talala"],"ans":"B","xp":"Cô muốn 'a job that allows me to work from home'; bảng: Delacruz – Work remotely → (B)."},{"n":67,"q":"What is the man nervous about doing?","qvi":"Người đàn ông hồi hộp về việc gì?","opts":["Taking a business trip","Starting his own business","Giving an important presentation","Applying for a promotion"],"vi":["Đi công tác","Mở công ty riêng","Thuyết trình quan trọng","Ứng tuyển vị trí cao hơn"],"ans":"D","xp":"'an opening for a department head that I'm thinking about applying for. It'd be a big step up... so I'm nervous' → ứng tuyển thăng chức → (D)."}],"a":"XC-T08-65-67.mp3","img":"g65.png"},{"ns":[68,70],"script":[["M","Good afternoon. I'm calling about the library's weekly book clubs. I work as a factory foreman, and one of my team members told me about this new activity.","Chào buổi chiều. Tôi gọi về các câu lạc bộ sách hằng tuần của thư viện. Tôi là quản đốc nhà máy, và một người trong nhóm tôi đã kể về hoạt động mới này."],["W","There's a different book club meeting every evening, except Sundays.","Mỗi tối có một câu lạc bộ sách khác nhau, trừ Chủ Nhật."],["M","All right. I'd be free for the Wednesday group, if there's space available.","Được. Tôi rảnh cho nhóm thứ Tư, nếu còn chỗ."],["W","Of course. You'll need to have a valid library card to join. If you give me your phone number, I'll have the group leader for that day contact you.","Tất nhiên. Anh cần có thẻ thư viện còn hạn để tham gia. Nếu anh cho tôi số điện thoại, tôi sẽ nhờ trưởng nhóm của ngày đó liên lạc với anh."],["M","Thanks. My name is Glenn Willis, and my number is 555-1897. My card is about to expire, though, so I'll stop by tomorrow and take care of renewing it.","Cảm ơn. Tôi tên Glenn Willis, số điện thoại là 555-1897. Nhưng thẻ của tôi sắp hết hạn, nên mai tôi sẽ ghé gia hạn."],["W","That'd be great.","Vậy thì tốt quá."]],"qs":[{"n":68,"q":"What is the man's occupation?","qvi":"Người đàn ông làm nghề gì?","opts":["Delivery driver","Professional editor","Certified accountant","Factory supervisor"],"vi":["Tài xế giao hàng","Biên tập viên","Kế toán có chứng chỉ","Quản đốc nhà máy"],"ans":"D","xp":"'I work as a factory foreman' → foreman = supervisor → (D)."},{"n":69,"q":"Look at the graphic. Who will contact the man?","qvi":"Nhìn hình. Ai sẽ liên lạc với người đàn ông?","opts":["Stanley Pickard","Brenda Kinsley","Tony Malone","Dawn Terrell"],"vi":["Stanley Pickard","Brenda Kinsley","Tony Malone","Dawn Terrell"],"ans":"C","xp":"Ông chọn 'the Wednesday group'; bảng: Wednesday, Friday – Tony Malone → (C)."},{"n":70,"q":"Why will the man visit the library tomorrow?","qvi":"Vì sao ngày mai người đàn ông đến thư viện?","opts":["To pay a late fee","To return some books","To renew a library card","To pick up an application form"],"vi":["Để trả phí trễ hạn","Để trả sách","Để gia hạn thẻ thư viện","Để lấy mẫu đơn"],"ans":"C","xp":"'My card is about to expire... I'll stop by tomorrow and take care of renewing it' → (C)."}],"a":"XC-T08-68-70.mp3","img":"g68.png"}],"p4":[{"ns":[71,73],"script":[["","Good morning, everyone, and thanks for coming to our monthly manager meeting. I'd like to inform you that Sakura Agano will be taking four weeks off so that she can recover from her medical issues. This poses a challenge, as our department store's head office requires that we have at least two managers working every shift. We'll need all of you to take on extra work, especially in the evenings. If anyone would like to offer to work more, please e-mail me sometime this week. Otherwise, I'll create the schedule myself, trying to be as fair as possible.","Chào buổi sáng mọi người, cảm ơn đã đến buổi họp quản lý hằng tháng. Tôi muốn thông báo rằng Sakura Agano sẽ nghỉ bốn tuần để điều trị sức khỏe. Điều này gây khó khăn vì trụ sở chính của trung tâm thương mại yêu cầu mỗi ca phải có ít nhất hai quản lý. Chúng ta cần tất cả mọi người làm thêm, đặc biệt là buổi tối. Ai muốn đăng ký làm thêm thì hãy e-mail cho tôi trong tuần này. Nếu không, tôi sẽ tự lập lịch sao cho công bằng nhất có thể."]],"qs":[{"n":71,"q":"Who most likely are the listeners?","qvi":"Người nghe nhiều khả năng là ai?","opts":["Security guards","Department store managers","Assembly line workers","Newly hired accountants"],"vi":["Nhân viên bảo vệ","Quản lý trung tâm thương mại","Công nhân dây chuyền lắp ráp","Kế toán mới tuyển"],"ans":"B","xp":"'our monthly manager meeting... our department store's head office' → quản lý trung tâm thương mại → (B)."},{"n":72,"q":"What is the main topic of the meeting?","qvi":"Chủ đề chính của cuộc họp là gì?","opts":["An upcoming industry event","A coworker's absence","A relocation of the office","A new vacation policy"],"vi":["Sự kiện ngành sắp tới","Một đồng nghiệp vắng mặt","Chuyển văn phòng","Chính sách nghỉ phép mới"],"ans":"B","xp":"'Sakura Agano will be taking four weeks off' và cả bài nói về việc thiếu người → (B)."},{"n":73,"q":"According to the speaker, why should listeners send him an e-mail?","qvi":"Theo người nói, vì sao người nghe nên gửi e-mail cho anh ấy?","opts":["To volunteer for extra shifts","To outline salary increases","To report policy violations","To schedule a training session"],"vi":["Để tình nguyện làm thêm ca","Để trình bày việc tăng lương","Để báo vi phạm quy định","Để lên lịch đào tạo"],"ans":"A","xp":"'If anyone would like to offer to work more, please e-mail me' → (A)."}],"a":"XC-T08-71-73.mp3"},{"ns":[74,76],"script":[["","Good morning. This message is for Joseph McCullen. This is Kalyani calling from Sterling Event Planning. I'm preparing the decorations for your upcoming event. I need to find out which color you would like for the centerpieces. The formal dinner for your employees is on July 22, and the florist needs at least ten days' notice. If you'd like to see what other customers have chosen in the past, you should visit the photo gallery on our Web site. This might help you to make a decision. Please call me back at 555-6331. Thank you.","Chào buổi sáng. Tin nhắn này gửi ông Joseph McCullen. Tôi là Kalyani ở công ty tổ chức sự kiện Sterling. Tôi đang chuẩn bị trang trí cho sự kiện sắp tới của ông. Tôi cần biết ông muốn màu gì cho lẵng hoa đặt giữa bàn. Bữa tối trang trọng cho nhân viên của ông diễn ra ngày 22 tháng 7, và người bán hoa cần báo trước ít nhất mười ngày. Nếu muốn xem các khách hàng trước đã chọn gì, ông có thể xem thư viện ảnh trên trang web của chúng tôi. Điều này có thể giúp ông quyết định. Vui lòng gọi lại cho tôi theo số 555-6331. Cảm ơn ông."]],"qs":[{"n":74,"q":"What does the caller want to know about?","qvi":"Người gọi muốn biết về điều gì?","opts":["An event budget","A start time","A color preference","A guest list"],"vi":["Ngân sách sự kiện","Giờ bắt đầu","Màu sắc ưa thích","Danh sách khách mời"],"ans":"C","xp":"'I need to find out which color you would like for the centerpieces' → (C)."},{"n":75,"q":"What is scheduled to happen on July 22?","qvi":"Ngày 22 tháng 7 sẽ diễn ra việc gì?","opts":["A job position will be filled.","A store will be remodeled.","A sale promotion will end.","A banquet will be held."],"vi":["Một vị trí sẽ được tuyển xong.","Một cửa hàng sẽ được sửa sang.","Đợt khuyến mãi sẽ kết thúc.","Một bữa tiệc sẽ được tổ chức."],"ans":"D","xp":"'The formal dinner for your employees is on July 22' → formal dinner = banquet → (D)."},{"n":76,"q":"According to the speaker, why should the listener visit a Web site?","qvi":"Theo người nói, vì sao người nghe nên vào trang web?","opts":["To check a list of services","To view some images","To submit a form","To provide a recommendation"],"vi":["Để xem danh sách dịch vụ","Để xem hình ảnh","Để nộp mẫu đơn","Để đưa ra đề xuất"],"ans":"B","xp":"'you should visit the photo gallery on our Web site' → xem ảnh → (B)."}],"a":"XC-T08-74-76.mp3"},{"ns":[77,79],"script":[["","Finally on today's agenda, I want to remind you all that the holiday season is a time to give back to the less fortunate. Charities such as the Manhattan Homeless Shelter and the Poverty Relief Fund are collecting financial contributions as well as food and clothing. In addition, Kimberly Ivy has arranged for a special collection of canned goods. She's the owner of Ivy Couriers and has offered to use her delivery vans to transport food to various food banks. Simply bring your goods here to the office on November 10, and they will be collected. I'll e-mail you a list of the types of items that are needed most. Thank you for your consideration.","Cuối cùng trong chương trình hôm nay, tôi muốn nhắc mọi người rằng mùa lễ là dịp để giúp đỡ những người kém may mắn. Các tổ chức từ thiện như Mái ấm cho người vô gia cư Manhattan và Quỹ Xóa đói giảm nghèo đang quyên góp tiền cũng như thực phẩm và quần áo. Ngoài ra, Kimberly Ivy đã tổ chức một đợt quyên góp đồ hộp đặc biệt. Bà là chủ công ty Ivy Couriers và đã đề nghị dùng xe giao hàng của mình chở thực phẩm đến các ngân hàng thực phẩm. Mọi người chỉ cần mang đồ đến văn phòng vào ngày 10 tháng 11, đồ sẽ được thu gom. Tôi sẽ e-mail cho mọi người danh sách các loại đồ cần nhất. Cảm ơn mọi người đã cân nhắc."]],"qs":[{"n":77,"q":"What is the speaker mainly discussing?","qvi":"Người nói chủ yếu bàn về điều gì?","opts":["A holiday break","Company regulations","A retirement party","Donation opportunities"],"vi":["Kỳ nghỉ lễ","Quy định công ty","Tiệc nghỉ hưu","Cơ hội quyên góp"],"ans":"D","xp":"Cả bài nói về các tổ chức từ thiện đang quyên góp và đợt thu gom đồ hộp → cơ hội quyên góp → (D). (A) lặp từ holiday."},{"n":78,"q":"Who is Kimberly Ivy?","qvi":"Kimberly Ivy là ai?","opts":["A new employee","A business owner","A charity founder","A guest speaker"],"vi":["Nhân viên mới","Chủ doanh nghiệp","Người sáng lập tổ chức từ thiện","Diễn giả khách mời"],"ans":"B","xp":"'She's the owner of Ivy Couriers' → chủ doanh nghiệp → (B)."},{"n":79,"q":"What does the speaker say he will do?","qvi":"Người nói nói sẽ làm gì?","opts":["Send some information","Collect completed forms","Purchase some items","Assign group tasks"],"vi":["Gửi thông tin","Thu các mẫu đơn đã điền","Mua đồ","Phân công nhóm"],"ans":"A","xp":"'I'll e-mail you a list of the types of items that are needed most' → gửi thông tin → (A)."}],"a":"XC-T08-77-79.mp3"},{"ns":[80,82],"script":[["","Good afternoon, and welcome to the Longmont Farm Tour. I'm your guide, Helen, and today I'll be showing you around. You'll get to see the cows in our milking room, where we collect the milk that gets sold and made into cheese, yogurt, ice cream, and more. I've provided you each with a pair of rubber boots to wear. It rained heavily last night, so the fields are quite muddy. Don't forget to hold on to your visitor pass. You can exchange it for a coupon for ice cream at the end of the tour.","Chào buổi chiều, chào mừng đến với chuyến tham quan Trang trại Longmont. Tôi là Helen, hướng dẫn viên, hôm nay tôi sẽ dẫn mọi người đi tham quan. Mọi người sẽ được xem những con bò trong phòng vắt sữa, nơi chúng tôi lấy sữa để bán và làm phô mai, sữa chua, kem, v.v. Tôi đã phát cho mỗi người một đôi ủng cao su. Tối qua mưa to nên cánh đồng khá lầy. Đừng quên giữ thẻ khách tham quan. Cuối chuyến đi, mọi người có thể đổi thẻ lấy phiếu ăn kem."]],"qs":[{"n":80,"q":"Where most likely are the listeners?","qvi":"Người nghe nhiều khả năng đang ở đâu?","opts":["At a dairy farm","At a city park","At a sports complex","At a golf course"],"vi":["Ở trang trại bò sữa","Ở công viên thành phố","Ở khu thể thao","Ở sân golf"],"ans":"A","xp":"'Longmont Farm Tour... cows in our milking room' → trang trại bò sữa → (A)."},{"n":81,"q":"Why does the speaker say, \"It rained heavily last night\"?","qvi":"Vì sao người nói nói \"tối qua mưa to\"?","opts":["She is proposing canceling an activity.","She wants to apologize for a delay.","She is explaining the need for some gear.","She will get some help from a coworker."],"vi":["Cô đề xuất hủy một hoạt động.","Cô muốn xin lỗi vì chậm trễ.","Cô giải thích vì sao cần đồ bảo hộ.","Cô sẽ nhờ đồng nghiệp giúp."],"ans":"C","xp":"Ngay trước đó: 'I've provided you each with a pair of rubber boots' → mưa to, đồng lầy nên cần ủng → (C)."},{"n":82,"q":"What are the listeners reminded to do?","qvi":"Người nghe được nhắc làm gì?","opts":["Hold their visitor passes","Refer to the game schedule","Try a new ride","Use a rear parking lot"],"vi":["Giữ thẻ khách tham quan","Xem lịch thi đấu","Thử trò chơi mới","Dùng bãi đỗ xe phía sau"],"ans":"A","xp":"'Don't forget to hold on to your visitor pass' → (A)."}],"a":"XC-T08-80-82.mp3"},{"ns":[83,85],"script":[["","Good afternoon. This is Tyler from Sheridan Sports. I was just looking over the packaging you sent for our new baseball shoes. Unfortunately, there's an issue. The name of our company is spelled wrong on the side of the box. It's correct on the top panel but not on the side. I'm glad I noticed this before we started putting products in them, or that would have been even worse. We'll need all of the boxes replaced as soon as possible, so please let me know when you think you can get those to us.","Chào buổi chiều. Tôi là Tyler ở Sheridan Sports. Tôi vừa xem bao bì anh gửi cho mẫu giày bóng chày mới của chúng tôi. Tiếc là có vấn đề. Tên công ty chúng tôi bị viết sai chính tả ở mặt bên hộp. Mặt trên thì đúng nhưng mặt bên thì sai. May mà tôi phát hiện trước khi bỏ sản phẩm vào, nếu không còn tệ hơn. Chúng tôi cần thay toàn bộ hộp càng sớm càng tốt, nên hãy cho tôi biết khi nào anh nghĩ có thể giao hộp mới cho chúng tôi."]],"qs":[{"n":83,"q":"What does the speaker's company produce?","qvi":"Công ty của người nói sản xuất gì?","opts":["Formal clothing","Camping gear","Athletic footwear","Healthy snacks"],"vi":["Quần áo trang trọng","Đồ cắm trại","Giày thể thao","Đồ ăn vặt lành mạnh"],"ans":"C","xp":"'our new baseball shoes' → giày thể thao → (C)."},{"n":84,"q":"What does the speaker tell the listener about?","qvi":"Người nói cho người nghe biết về điều gì?","opts":["An unexpected order from a client","A misprint on the packaging","A suggestion for an ad campaign","A change in a release date"],"vi":["Đơn hàng bất ngờ từ khách","Lỗi in trên bao bì","Gợi ý cho chiến dịch quảng cáo","Thay đổi ngày ra mắt"],"ans":"B","xp":"'The name of our company is spelled wrong on the side of the box' → in sai trên bao bì → (B)."},{"n":85,"q":"What does the speaker ask the listener to do?","qvi":"Người nói yêu cầu người nghe làm gì?","opts":["Send a sample to be checked","Find a place to store some items","Cancel an express order","Estimate a delivery date"],"vi":["Gửi mẫu để kiểm tra","Tìm chỗ cất đồ","Hủy đơn hàng gấp","Ước tính ngày giao hàng"],"ans":"D","xp":"'please let me know when you think you can get those to us' → báo khi nào giao được → (D)."}],"a":"XC-T08-83-85.mp3"},{"ns":[86,88],"script":[["","We're back with the local news update on Medford Radio, 101.6 FM. There's big news coming from Belmont Hall this week. The facility is well-known in the community for hosting creative and unusual concerts and plays, most recently an event with a group of acrobats. Well, the theater is now getting ready for its biggest show yet—a night of dramatic readings from world-famous actress Elisa Brown on Saturday, May 12. Yes, right here in Medford! It looks like our little town is finding a way to stand out. Tickets are sure to go fast, so call Belmont Hall's box office to get yours before they're gone.","Chúng tôi trở lại với bản tin địa phương trên đài Medford Radio, 101.6 FM. Tuần này có tin lớn từ Belmont Hall. Nơi này nổi tiếng trong cộng đồng vì tổ chức các buổi hòa nhạc và vở kịch sáng tạo, độc đáo, gần đây nhất là sự kiện với một nhóm diễn viên nhào lộn. Giờ nhà hát đang chuẩn bị cho buổi diễn lớn nhất từ trước đến nay: một đêm đọc diễn cảm của nữ diễn viên nổi tiếng thế giới Elisa Brown vào thứ Bảy, ngày 12 tháng 5. Vâng, ngay tại Medford! Có vẻ thị trấn nhỏ của chúng ta đang tìm được cách để nổi bật. Vé chắc chắn sẽ hết nhanh, nên hãy gọi phòng vé Belmont Hall để mua trước khi hết."]],"qs":[{"n":86,"q":"What does the speaker say Belmont Hall is famous for?","qvi":"Người nói cho biết Belmont Hall nổi tiếng về điều gì?","opts":["It hosts unique performances.","It is one of the oldest theaters.","It financially supports local artists.","It offers educational programs."],"vi":["Tổ chức các buổi diễn độc đáo.","Là một trong những nhà hát lâu đời nhất.","Hỗ trợ tài chính cho nghệ sĩ địa phương.","Có chương trình giáo dục."],"ans":"A","xp":"'well-known in the community for hosting creative and unusual concerts and plays' → buổi diễn độc đáo → (A)."},{"n":87,"q":"Who is Elisa Brown?","qvi":"Elisa Brown là ai?","opts":["An event planner","A musician","A radio announcer","An actress"],"vi":["Người tổ chức sự kiện","Nhạc sĩ","Phát thanh viên","Nữ diễn viên"],"ans":"D","xp":"'world-famous actress Elisa Brown' → (D)."},{"n":88,"q":"Why does the speaker say, \"Yes, right here in Medford\"?","qvi":"Vì sao người nói nói \"Vâng, ngay tại Medford\"?","opts":["To suggest changing a venue","To support the local community","To correct a previous error","To express surprise about an event"],"vi":["Để đề xuất đổi địa điểm","Để ủng hộ cộng đồng địa phương","Để sửa lỗi trước đó","Để bày tỏ ngạc nhiên về sự kiện"],"ans":"D","xp":"Một ngôi sao nổi tiếng thế giới đến thị trấn nhỏ; ngay sau đó 'our little town is finding a way to stand out' → người nói ngạc nhiên, phấn khởi về sự kiện → (D)."}],"a":"XC-T08-86-88.mp3"},{"ns":[89,91],"script":[["","We've received a lot of positive feedback about your efficiency in repairing computer problems and solving software issues around the office. However, scores for professionalism have been low, so there's definitely room for improvement. Therefore, our next activity will focus on customer service skills. First, you will watch a brief video of a typical interaction. Then, I'll give you some strategies for handling difficult situations. After that, you'll form groups of three to role-play some scenarios. It doesn't matter to me what the groups look like. I haven't prepared a list of participants. If everyone is ready, let's begin.","Chúng tôi nhận được nhiều phản hồi tốt về việc các bạn sửa lỗi máy tính và xử lý sự cố phần mềm trong văn phòng rất hiệu quả. Tuy nhiên, điểm về tác phong chuyên nghiệp còn thấp, nên chắc chắn còn chỗ cần cải thiện. Vì vậy, hoạt động tiếp theo sẽ tập trung vào kỹ năng phục vụ khách hàng. Đầu tiên, các bạn sẽ xem một đoạn video ngắn về một tình huống giao tiếp điển hình. Sau đó, tôi sẽ đưa ra vài cách xử lý tình huống khó. Rồi các bạn sẽ chia nhóm ba người để đóng vai một số tình huống. Nhóm thế nào cũng được. Tôi không chuẩn bị danh sách người tham gia. Nếu mọi người sẵn sàng, chúng ta bắt đầu."]],"qs":[{"n":89,"q":"Who most likely is the speaker addressing?","qvi":"Người nói nhiều khả năng đang nói với ai?","opts":["Video editors","Computer technicians","Bank tellers","Restaurant serving staff"],"vi":["Biên tập viên video","Kỹ thuật viên máy tính","Giao dịch viên ngân hàng","Nhân viên phục vụ nhà hàng"],"ans":"B","xp":"'your efficiency in repairing computer problems and solving software issues' → kỹ thuật viên máy tính → (B)."},{"n":90,"q":"Why is the speaker giving the talk?","qvi":"Vì sao người nói có bài nói này?","opts":["To give an overview of an activity","To review a revised policy","To explain how to use a device","To present an employee award"],"vi":["Để giới thiệu tổng quan một hoạt động","Để xem lại chính sách sửa đổi","Để hướng dẫn dùng thiết bị","Để trao giải nhân viên"],"ans":"A","xp":"'our next activity will focus on customer service skills. First... Then... After that...' → giới thiệu hoạt động → (A)."},{"n":91,"q":"What does the speaker imply when he says, \"I haven't prepared a list of participants\"?","qvi":"Người nói ngụ ý gì khi nói \"Tôi không chuẩn bị danh sách người tham gia\"?","opts":["The listeners should fill in a sign-up sheet.","The listeners are not required to attend the meeting.","The listeners can make suggestions for a guest list.","The listeners should form their own groups."],"vi":["Người nghe nên điền phiếu đăng ký.","Người nghe không bắt buộc dự họp.","Người nghe có thể đề xuất danh sách khách.","Người nghe tự chia nhóm."],"ans":"D","xp":"Trước đó: 'you'll form groups of three... It doesn't matter to me what the groups look like' → không có danh sách sẵn, người nghe tự lập nhóm → (D)."}],"a":"XC-T08-89-91.mp3"},{"ns":[92,94],"script":[["","To begin today's staff meeting, I'd like to apologize for relocating this meeting to the second floor. I had forgotten that the break room was being painted. The main thing I want to cover is the results of our employee survey. Almost all of you suggested that we move to a monthly system for setting the work schedule rather than our current approach of issuing it week by week. The management team has decided to go ahead with that change. Speaking of looking ahead, many of you will be assigned to longer shifts on August 5. This is because the new Boyd-9 smartphone will be launched on that day, and we're expecting a lot of customers.","Để bắt đầu buổi họp nhân viên hôm nay, tôi xin lỗi vì đã dời cuộc họp lên tầng hai. Tôi quên mất là phòng nghỉ đang được sơn. Điều chính tôi muốn nói là kết quả khảo sát nhân viên. Hầu như tất cả các bạn đề nghị chuyển sang xếp lịch làm việc theo tháng thay vì phát lịch từng tuần như hiện nay. Ban quản lý đã quyết định áp dụng thay đổi đó. Nói về sắp tới, nhiều bạn sẽ được xếp ca dài hơn vào ngày 5 tháng 8. Lý do là điện thoại thông minh Boyd-9 mới sẽ ra mắt hôm đó và chúng ta dự kiến có rất đông khách."]],"qs":[{"n":92,"q":"Why does the speaker apologize?","qvi":"Vì sao người nói xin lỗi?","opts":["A meeting location was moved.","There are not enough seats.","Her talk has begun later than expected.","A deadline has been changed."],"vi":["Địa điểm họp bị dời.","Không đủ chỗ ngồi.","Bài nói bắt đầu muộn hơn dự kiến.","Hạn chót bị thay đổi."],"ans":"A","xp":"'I'd like to apologize for relocating this meeting to the second floor' → (A)."},{"n":93,"q":"According to the speaker, what do employees want to change?","qvi":"Theo người nói, nhân viên muốn thay đổi điều gì?","opts":["A meeting day","A scheduling method","A break duration","A payment system"],"vi":["Ngày họp","Cách xếp lịch","Thời gian nghỉ","Hệ thống trả lương"],"ans":"B","xp":"'move to a monthly system for setting the work schedule rather than... week by week' → cách xếp lịch → (B)."},{"n":94,"q":"What will happen on August 5?","qvi":"Ngày 5 tháng 8 sẽ diễn ra việc gì?","opts":["A new product will be launched.","A training workshop will be conducted.","A VIP guest will visit the business.","A shipping policy will be changed."],"vi":["Một sản phẩm mới ra mắt.","Một buổi đào tạo được tổ chức.","Một khách VIP đến thăm.","Chính sách giao hàng thay đổi."],"ans":"A","xp":"'the new Boyd-9 smartphone will be launched on that day' → (A)."}],"a":"XC-T08-92-94.mp3"},{"ns":[95,97],"script":[["","Hi, Ms. Mayfield. This is Laurel Hamlin from Coventry Enterprises. I can't wait to see the fashion concepts you've come up with for our new women's line of formalwear. When you come to my office for our meeting on Thursday, I just want to make sure you don't have any problems. When you get to the Auburn Building, you should first stop at the reception desk to show a valid ID. I'll put you on the list, and the receptionist will have a visitor badge ready for you to wear. Then just head over to my office, which is number 125. If you have any trouble finding it, please don't hesitate to give me a call. See you on Thursday!","Chào chị Mayfield. Tôi là Laurel Hamlin ở Coventry Enterprises. Tôi rất mong được xem các ý tưởng thời trang chị đưa ra cho dòng trang phục dạ hội nữ mới của chúng tôi. Khi chị đến văn phòng tôi để họp vào thứ Năm, tôi muốn chắc chị không gặp trở ngại gì. Khi đến tòa nhà Auburn, chị hãy ghé quầy lễ tân trước để xuất trình giấy tờ tùy thân hợp lệ. Tôi sẽ ghi tên chị vào danh sách, và lễ tân sẽ chuẩn bị sẵn thẻ khách cho chị đeo. Sau đó chị cứ đến văn phòng tôi, số 125. Nếu khó tìm thì đừng ngại gọi cho tôi. Hẹn gặp chị thứ Năm!"]],"qs":[{"n":95,"q":"What will the meeting on Thursday probably be about?","qvi":"Cuộc họp thứ Năm có lẽ về chủ đề gì?","opts":["Employee healthcare","Financial services","Clothing designs","Building repairs"],"vi":["Chăm sóc sức khỏe nhân viên","Dịch vụ tài chính","Thiết kế quần áo","Sửa chữa tòa nhà"],"ans":"C","xp":"'the fashion concepts you've come up with for our new women's line of formalwear' → thiết kế quần áo → (C)."},{"n":96,"q":"What should Ms. Mayfield do when she arrives at the Auburn Building?","qvi":"Chị Mayfield nên làm gì khi đến tòa nhà Auburn?","opts":["Ask to have her parking pass stamped","Wait in the lobby for the speaker","Add her name to a visitor sign-up sheet","Present a form of identification"],"vi":["Xin đóng dấu vé đỗ xe","Đợi người nói ở sảnh","Ghi tên vào sổ khách","Xuất trình giấy tờ tùy thân"],"ans":"D","xp":"'first stop at the reception desk to show a valid ID' → (D). (C) sai vì người nói tự ghi tên chị vào danh sách."},{"n":97,"q":"Look at the graphic. Where is the speaker's office?","qvi":"Nhìn hình. Văn phòng của người nói ở đâu?","opts":["In the North Wing","In the East Wing","In the South Wing","In the West Wing"],"vi":["Ở khu phía Bắc","Ở khu phía Đông","Ở khu phía Nam","Ở khu phía Tây"],"ans":"B","xp":"'my office, which is number 125'; bảng: Offices 120–139 – East Wing → (B)."}],"a":"XC-T08-95-97.mp3","img":"g95.png"},{"ns":[98,100],"script":[["","Thank you all for being here for this press conference to answer your questions about our expansion into the Asian market. We have been seeking a partnership with a South Korean company to help boost our brand and improve distribution. We have several companies in mind at the moment, but I cannot comment on that further until the negotiations are completed. What I can tell you, though, is that we expect the market value of our company to increase. You can see on this chart that we're at about 45 million dollars now, but we soon hope to surpass some of our competitors. Now I'd like to introduce Stacy Mayer, who will explain some of the merchandise we'll add to our line to appeal to consumers in Asia.","Cảm ơn mọi người đã đến buổi họp báo hôm nay để chúng tôi trả lời câu hỏi về việc mở rộng sang thị trường châu Á. Chúng tôi đang tìm đối tác là một công ty Hàn Quốc để giúp quảng bá thương hiệu và cải thiện phân phối. Hiện chúng tôi đang cân nhắc vài công ty, nhưng chưa thể nói thêm cho đến khi đàm phán xong. Điều tôi có thể nói là chúng tôi kỳ vọng giá trị thị trường của công ty sẽ tăng. Như mọi người thấy trên biểu đồ, hiện chúng tôi ở mức khoảng 45 triệu đô la, nhưng hy vọng sớm vượt qua một số đối thủ. Bây giờ tôi xin giới thiệu Stacy Mayer, người sẽ giới thiệu một số mặt hàng chúng tôi sẽ bổ sung để thu hút người tiêu dùng châu Á."]],"qs":[{"n":98,"q":"Who most likely is the speaker addressing?","qvi":"Người nói nhiều khả năng đang nói với ai?","opts":["Language translators","News journalists","Job candidates","Financial experts"],"vi":["Biên dịch viên","Phóng viên báo chí","Ứng viên xin việc","Chuyên gia tài chính"],"ans":"B","xp":"'Thank you all for being here for this press conference to answer your questions' → họp báo → nhà báo → (B)."},{"n":99,"q":"Look at the graphic. Which company does the speaker most likely work at?","qvi":"Nhìn hình. Người nói nhiều khả năng làm ở công ty nào?","opts":["Tolliver Industries","Marietta Co.","Syder Enterprises","Barnes, Inc."],"vi":["Tolliver Industries","Marietta Co.","Syder Enterprises","Barnes, Inc."],"ans":"C","xp":"'we're at about 45 million dollars now'; trên biểu đồ, công ty có giá trị khoảng 45 triệu đô là Syder Enterprises → (C)."},{"n":100,"q":"What will the listeners hear about next?","qvi":"Người nghe sẽ được nghe về điều gì tiếp theo?","opts":["Some new lines of products","A recent research study","Some employee achievements","An advertisement layout"],"vi":["Dòng sản phẩm mới","Nghiên cứu gần đây","Thành tích nhân viên","Bố cục quảng cáo"],"ans":"A","xp":"'Stacy Mayer, who will explain some of the merchandise we'll add to our line' → (A)."}],"a":"XC-T08-98-100.mp3","img":"g98.png"}]},"rc":{"p5":[{"n":101,"q":"Please call ------- immediately at this 24-hour customer service hotline if your credit card is lost or stolen.","opts":["we","our","us","ourselves"],"ans":"C","xp":"Đại từ. Sau động từ 'call' cần tân ngữ → (C) us. (A) chủ ngữ, (B) tính từ sở hữu, (D) phản thân (chủ ngữ không phải 'we').\nDịch: Nếu thẻ tín dụng bị mất hoặc bị đánh cắp, vui lòng gọi ngay cho chúng tôi theo đường dây nóng chăm sóc khách hàng 24 giờ này."},{"n":102,"q":"Team members are ------- that the project manager extended the deadline from April 1 to April 10.","opts":["thank","thankful","thankfully","thanks"],"ans":"B","xp":"Từ loại. Sau 'are' cần tính từ; be thankful that... = biết ơn vì... → (B). (A)(D) động từ/danh từ, (C) trạng từ.\nDịch: Các thành viên nhóm rất biết ơn vì quản lý dự án đã lùi hạn chót từ 1/4 sang 10/4."},{"n":103,"q":"Ms. Henderson ------- that visitors wear an ID badge at all times during their visit.","opts":["insists","insisting","to insist","to be insisted"],"ans":"A","xp":"Chia động từ. Câu thiếu động từ chính, chủ ngữ số ít 'Ms. Henderson' → (A) insists. (B) V-ing, (C)(D) to V không làm động từ chính.\nDịch: Bà Henderson yêu cầu khách luôn đeo thẻ tên trong suốt chuyến thăm."},{"n":104,"q":"The parking lot located on Marron Street will be closed until ------- notice.","opts":["effective","constant","periodic","further"],"ans":"D","xp":"Từ vựng. until further notice = cho đến khi có thông báo mới → (D). (A) effective 'có hiệu lực', (B) constant 'liên tục', (C) periodic 'định kỳ' không tạo cụm này.\nDịch: Bãi đỗ xe trên phố Marron sẽ đóng cửa cho đến khi có thông báo mới."},{"n":105,"q":"Job seekers who are ------- in the position should e-mail their resumé with cover letter and references to Ashley Waller.","opts":["interesting","interested","interests","interest"],"ans":"B","xp":"Từ loại. be interested in = quan tâm đến (dùng cho người) → (B). (A) interesting 'thú vị' (dùng cho vật), (C)(D) danh từ/động từ.\nDịch: Người tìm việc quan tâm đến vị trí này nên e-mail sơ yếu lý lịch kèm thư xin việc và người giới thiệu cho Ashley Waller."},{"n":106,"q":"The software has been recently updated, ------- there are some changes to the menu.","opts":["lastly","so","because","then"],"ans":"B","xp":"Liên từ. Hai mệnh đề quan hệ nguyên nhân – kết quả: phần mềm vừa cập nhật → nên menu có thay đổi → (B) so 'vì vậy'. (C) because đảo ngược nghĩa, (A) lastly, (D) then là trạng từ không nối hai mệnh đề sau dấu phẩy.\nDịch: Phần mềm vừa được cập nhật nên menu có một số thay đổi."},{"n":107,"q":"Information about the drug is ------- available to patients through the hospital's Web site.","opts":["ready","readily","readier","readiest"],"ans":"B","xp":"Từ loại. Trước tính từ 'available' cần trạng từ → (B) readily; readily available = có sẵn, dễ tiếp cận. (A) tính từ, (C)(D) so sánh hơn/nhất.\nDịch: Thông tin về loại thuốc này luôn có sẵn cho bệnh nhân trên trang web của bệnh viện."},{"n":108,"q":"After receiving several orders with overly ripe fruits, Beechwood Catering's owner tried to find a new food -------.","opts":["presenter","container","supplier","diner"],"ans":"C","xp":"Từ vựng. Nhận trái cây quá chín → tìm nhà cung cấp thực phẩm mới → (C) supplier. (A) presenter 'người thuyết trình', (B) container 'hộp đựng', (D) diner 'thực khách'.\nDịch: Sau khi nhận nhiều đơn hàng trái cây chín quá, chủ công ty Beechwood Catering đã tìm nhà cung cấp thực phẩm mới."},{"n":109,"q":"Spot-on Delivery will switch to hybrid vehicles to minimize ------- fuel expenses.","opts":["rising","closing","limited","yielding"],"ans":"A","xp":"Từ vựng. minimize rising fuel expenses = giảm thiểu chi phí nhiên liệu đang tăng → (A). (B) closing 'đóng', (C) limited 'có hạn' (không cần giảm), (D) yielding 'mang lại' không hợp.\nDịch: Spot-on Delivery sẽ chuyển sang xe hybrid để giảm chi phí nhiên liệu đang tăng."},{"n":110,"q":"The start time for the training will not be ------- until Ms. Rudd checks everyone's schedules.","opts":["concluded","persuaded","decided","entitled"],"ans":"C","xp":"Từ vựng. Giờ bắt đầu sẽ không được quyết định cho đến khi bà Rudd kiểm tra lịch mọi người → (C) decided. (A) concluded 'kết thúc', (B) persuaded 'thuyết phục', (D) entitled 'được quyền' không hợp.\nDịch: Giờ bắt đầu buổi đào tạo sẽ chưa được quyết định cho đến khi bà Rudd kiểm tra lịch của mọi người."},{"n":111,"q":"Author Betty Glynn generated interest in her new novel ------- participating in several television interviews.","opts":["by","to","of","as"],"ans":"A","xp":"Giới từ. by + V-ing = bằng cách → 'by participating in several television interviews' → (A). (B)(C)(D) không chỉ cách thức.\nDịch: Tác giả Betty Glynn đã gây chú ý cho cuốn tiểu thuyết mới bằng cách tham gia nhiều cuộc phỏng vấn trên truyền hình."},{"n":112,"q":"All funds should be allotted and spent ------- according to a well-planned budget.","opts":["wise","wisely","wisdom","wiser"],"ans":"B","xp":"Từ loại. Bổ nghĩa cho động từ 'allotted and spent' cần trạng từ → (B) wisely 'một cách khôn ngoan'. (A)(D) tính từ, (C) danh từ.\nDịch: Mọi khoản tiền nên được phân bổ và chi tiêu khôn ngoan theo một ngân sách được lập kỹ."},{"n":113,"q":"After a few moments of -------, Ms. Wickham realized that the sign on the podium had a misprint.","opts":["observer","observative","observation","observe"],"ans":"C","xp":"Từ loại. Sau giới từ 'of' cần danh từ; 'a few moments of observation' = vài phút quan sát → (C). (A) observer là danh từ chỉ người (không hợp nghĩa), (B) tính từ, (D) động từ.\nDịch: Sau vài phút quan sát, bà Wickham nhận ra tấm biển trên bục phát biểu bị in sai."},{"n":114,"q":"Crosby Manufacturing was ------- bankruptcy last year, but the new CEO has turned the company around.","opts":["with","close to","along","nearby"],"ans":"B","xp":"Giới từ. be close to bankruptcy = suýt phá sản → (B). (A) with, (C) along, (D) nearby (thường là trạng từ/tính từ) không hợp.\nDịch: Năm ngoái Crosby Manufacturing suýt phá sản, nhưng giám đốc mới đã vực dậy công ty."},{"n":115,"q":"Experts ------- regard Belleview Hotel as the best value for business travelers in Austin.","opts":["wider","widely","widen","widest"],"ans":"B","xp":"Từ loại. Giữa chủ ngữ 'Experts' và động từ 'regard' cần trạng từ → (B) widely 'rộng rãi'. (A)(D) so sánh, (C) động từ.\nDịch: Giới chuyên gia đều đánh giá khách sạn Belleview đáng tiền nhất cho khách công tác ở Austin."},{"n":116,"q":"The main conference room is large ------- to seat the entire sales and finance teams at the same time.","opts":["even","enough","just","still"],"ans":"B","xp":"Cấu trúc. tính từ + enough + to V = đủ... để → 'large enough to seat' (B). (A) even, (C) just, (D) still không đứng sau tính từ theo cấu trúc này.\nDịch: Phòng họp chính đủ rộng để cả nhóm kinh doanh và nhóm tài chính ngồi cùng lúc."},{"n":117,"q":"Ms. Russell did not attend the banquet because her doctor put her on a ------- diet.","opts":["restriction","restrict","restrictive","restrictively"],"ans":"C","xp":"Từ loại. Giữa 'a' và danh từ 'diet' cần tính từ → (C) restrictive 'hạn chế'; a restrictive diet = chế độ ăn kiêng nghiêm ngặt. (A) danh từ, (B) động từ, (D) trạng từ.\nDịch: Bà Russell không dự tiệc vì bác sĩ yêu cầu bà ăn kiêng nghiêm ngặt."},{"n":118,"q":"Following the exhibit's grand opening, there will be a private ------- for the major donors.","opts":["malfunction","direction","occupation","reception"],"ans":"D","xp":"Từ vựng. a private reception = buổi tiệc chiêu đãi riêng → (D). (A) malfunction 'sự cố', (B) direction 'hướng', (C) occupation 'nghề nghiệp'.\nDịch: Sau lễ khai mạc triển lãm sẽ có buổi tiệc chiêu đãi riêng cho các nhà tài trợ lớn."},{"n":119,"q":"Sheila Slater gave a talk that was based on questions written by the audience members -------.","opts":["herself","themselves","ourselves","yourself"],"ans":"B","xp":"Đại từ phản thân. 'written by the audience members themselves' = do chính khán giả viết (nhấn mạnh) → đại từ số nhiều ngôi 3 (B). (A) số ít, (C)(D) sai ngôi.\nDịch: Sheila Slater có bài nói dựa trên các câu hỏi do chính khán giả viết."},{"n":120,"q":"As the airline ticket prices far exceeded the budget, the marketing team took the train to the conference -------.","opts":["instead","against","despite","otherwise"],"ans":"A","xp":"Trạng từ. 'đi tàu thay vì (máy bay)' → trạng từ cuối câu (A) instead 'thay vào đó'. (B)(C) là giới từ cần tân ngữ, (D) otherwise 'nếu không thì' không hợp.\nDịch: Vì vé máy bay vượt xa ngân sách, nhóm marketing đã đi tàu đến hội nghị thay vì đi máy bay."},{"n":121,"q":"Traffic conditions in Greenwood ------- worse and must be addressed by city officials.","opts":["growing","to grow","had to grow","have grown"],"ans":"D","xp":"Thì động từ. Câu thiếu động từ chính; tình trạng giao thông đã trở nên tệ hơn và giờ cần xử lý → hiện tại hoàn thành (D) have grown. (A) V-ing, (B) to V không làm động từ chính, (C) quá khứ hoàn thành không hợp với 'must be addressed' (hiện tại).\nDịch: Tình hình giao thông ở Greenwood ngày càng tệ và chính quyền thành phố phải giải quyết."},{"n":122,"q":"Text message alerts about new offers are available to those ------- signed up for our reminder service.","opts":["why","which","who","when"],"ans":"C","xp":"Đại từ quan hệ. Danh từ chỉ người 'those' (những người) + mệnh đề quan hệ thiếu chủ ngữ → (C) who. (A) why, (D) when chỉ lý do/thời gian, (B) which dùng cho vật.\nDịch: Tin nhắn báo ưu đãi mới dành cho những ai đã đăng ký dịch vụ nhắc nhở."},{"n":123,"q":"------- a post office, the Granger Building has recently been converted to a dance studio.","opts":["Formerly","Solely","Needlessly","Rarely"],"ans":"A","xp":"Trạng từ. 'Trước đây là bưu điện, nay chuyển thành phòng tập nhảy' → (A) Formerly 'trước đây'. (B) Solely 'duy nhất', (C) Needlessly 'không cần thiết', (D) Rarely 'hiếm khi'.\nDịch: Trước đây là bưu điện, tòa nhà Granger vừa được chuyển thành phòng tập nhảy."},{"n":124,"q":"The mayor of Pacheo ------- to dedicate the fountain in Kemper Park to the city's local firefighters.","opts":["declares","intends","refers","signifies"],"ans":"B","xp":"Từ vựng. intend to V = dự định → (B) intends. (A) declares 'tuyên bố' (thường + that), (C) refers (to + N), (D) signifies 'biểu thị' không đi với to V.\nDịch: Thị trưởng thành phố Pacheo dự định dành tặng đài phun nước ở công viên Kemper cho lực lượng cứu hỏa địa phương."},{"n":125,"q":"A commercial license issued by the state is needed ------- operate a large moving truck legally.","opts":["sometimes","regarding","in order to","as soon as"],"ans":"C","xp":"Liên từ/giới từ. Sau chỗ trống là động từ nguyên thể 'operate' → (C) in order to 'để'. (A) trạng từ, (B) regarding + N, (D) as soon as + mệnh đề.\nDịch: Cần có giấy phép thương mại do bang cấp để lái xe tải chở đồ lớn một cách hợp pháp."},{"n":126,"q":"The newly hired interns will require ongoing ------- until they are comfortable with their job responsibilities.","opts":["supervisor","supervision","supervises","supervised"],"ans":"B","xp":"Từ loại. Sau tính từ 'ongoing' và làm tân ngữ cho 'require' cần danh từ → (B) supervision 'sự giám sát'. (A) supervisor là danh từ đếm được số ít cần mạo từ, (C)(D) động từ.\nDịch: Các thực tập sinh mới sẽ cần được giám sát liên tục cho đến khi quen với công việc."},{"n":127,"q":"Humphrey Bank is working to keep customers informed ------- eliminating unnecessary paperwork.","opts":["unless","while","that","therefore"],"ans":"B","xp":"Liên từ. while + V-ing = trong khi (cùng lúc) → 'giữ khách hàng được cập nhật trong khi loại bỏ giấy tờ thừa' → (B). (A) unless 'trừ khi', (C) that, (D) therefore không hợp.\nDịch: Ngân hàng Humphrey đang nỗ lực cập nhật thông tin cho khách hàng đồng thời loại bỏ giấy tờ không cần thiết."},{"n":128,"q":"New staff members are ------- to renegotiate the contract terms after the sixty-day trial period is completed.","opts":["introductory","familiar","strict","eligible"],"ans":"D","xp":"Từ vựng. be eligible to V = đủ điều kiện để → (D). (A) introductory 'giới thiệu', (B) familiar (with), (C) strict 'nghiêm khắc' không hợp.\nDịch: Nhân viên mới đủ điều kiện thương lượng lại điều khoản hợp đồng sau khi hết 60 ngày thử việc."},{"n":129,"q":"Despite the store owner's considerable -------, the grand opening did not have a strong turnout.","opts":["optimistic","optimism","optimize","optimistically"],"ans":"B","xp":"Từ loại. Sau tính từ sở hữu + tính từ 'the store owner's considerable' cần danh từ → (B) optimism 'sự lạc quan'. (A) tính từ, (C) động từ, (D) trạng từ.\nDịch: Dù chủ cửa hàng rất lạc quan, buổi khai trương vẫn không có nhiều người đến."},{"n":130,"q":"------- the town's founding day with a parade is a tradition that goes back nearly one hundred years.","opts":["Celebrate","Celebrated","Celebration","Celebrating"],"ans":"D","xp":"Danh động từ. Chỗ trống đầu câu làm chủ ngữ và vẫn có tân ngữ 'the town's founding day' → V-ing (D) Celebrating. (A) động từ nguyên thể, (B) V3, (C) danh từ không có tân ngữ trực tiếp.\nDịch: Mừng ngày thành lập thị trấn bằng một cuộc diễu hành là truyền thống có từ gần một trăm năm trước."}],"p6":[{"ns":[131,134],"head":"Questions 131-134 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> Gladys Wheeler &lt;g.wheeler@wheeler-studio.com&gt;</p><p><b>From:</b> James Blackwell &lt;blackwell_j@hammettdept.com&gt;</p><p><b>Date:</b> January 23</p><p><b>Subject:</b> Hammett Department Store</p></div><p>Dear Ms. Wheeler,</p><p>I'm so pleased that you have confirmed your intention to design jackets for the upcoming winter season. <span class=\"blank\" data-n=\"131\">-------</span> Therefore, it is especially exciting to be working with you on this project. As a first step, I'd like to get together to brainstorm some ideas about colors and price points. Since our department store is known for its <span class=\"blank\" data-n=\"132\">-------</span> clothing, we want to make sure that we follow the trends. Diana Keasler, the assistant buyer for our store, will <span class=\"blank\" data-n=\"133\">-------</span> us for the meeting. We would appreciate <span class=\"blank\" data-n=\"134\">-------</span> some preliminary drawings. Please let me know what date would work well for you.</p><p>Sincerely,<br>James Blackwell</p>","vi":"Người nhận: Gladys Wheeler | Người gửi: James Blackwell | Ngày: 23/1 | Chủ đề: Trung tâm thương mại Hammett\n\nKính gửi chị Wheeler,\n\nTôi rất vui khi chị đã xác nhận sẽ thiết kế áo khoác cho mùa đông sắp tới. Tôi rất ấn tượng với các sản phẩm trong danh mục trực tuyến của chị. Vì vậy, được làm việc cùng chị trong dự án này thật đặc biệt thú vị. Bước đầu tiên, tôi muốn gặp để cùng lên ý tưởng về màu sắc và mức giá. Vì trung tâm thương mại của chúng tôi nổi tiếng với quần áo thời trang, chúng tôi muốn chắc chắn mình theo kịp xu hướng. Diana Keasler, trợ lý thu mua của cửa hàng, sẽ tham gia cuộc họp cùng chúng tôi. Chúng tôi rất mong được xem vài bản phác thảo ban đầu. Vui lòng cho tôi biết ngày nào thuận tiện cho chị.\n\nTrân trọng,\nJames Blackwell","qs":[{"n":131,"opts":["There are several ways to make this decision.","I was impressed with the items in your online catalog.","Attached you will find the contract with the necessary changes.","I already received several compliments on my clothing."],"ans":"B","xp":"Điền câu. Câu sau: 'Therefore, it is especially exciting to be working with you' → câu trước nêu lý do vui khi làm việc với cô: 'Tôi ấn tượng với sản phẩm trong danh mục trực tuyến của chị' → (B)."},{"n":132,"opts":["fashionably","fashions","fashioning","fashionable"],"ans":"D","xp":"Từ loại. Giữa 'its' và danh từ 'clothing' cần tính từ → (D) fashionable 'hợp thời trang'. (A) trạng từ, (B) danh từ/động từ, (C) V-ing."},{"n":133,"opts":["undergo","join","attend","remind"],"ans":"B","xp":"Từ vựng. join + người = tham gia cùng ai → 'will join us for the meeting' (B). (C) attend + sự kiện (attend the meeting), không + 'us'; (A) undergo 'trải qua', (D) remind 'nhắc'."},{"n":134,"opts":["views","to view","viewing","viewed"],"ans":"C","xp":"Động từ. appreciate + V-ing → (C) viewing; 'We would appreciate viewing...' = chúng tôi rất mong được xem."}]},{"ns":[135,138],"head":"Questions 135-138 refer to the following letter.","passage":"<p>Dear Webster City Resident,</p><p>The Webster City Library System strives <span class=\"blank\" data-n=\"135\">-------</span> a comfortable environment for patrons to study, read, and conduct research. In light of this, we are scheduling renovations at our Hollis Street location. The project will consist of two phases of construction <span class=\"blank\" data-n=\"136\">-------</span> a total of six months.</p><p>The work will begin on February 16 and will be carried out by local firm Benley Designs. Some sections of the library will be closed, and noisy equipment will be in operation. <span class=\"blank\" data-n=\"137\">-------</span> Should you need a quiet environment, our other sites will be available during their normal opening <span class=\"blank\" data-n=\"138\">-------</span>.</p><p>Sincerely,<br>Douglas Braun<br>Head Administrator, Webster City Library System</p>","vi":"Kính gửi cư dân thành phố Webster,\n\nHệ thống Thư viện thành phố Webster luôn nỗ lực tạo môi trường thoải mái để bạn đọc học tập, đọc sách và nghiên cứu. Vì vậy, chúng tôi lên lịch cải tạo chi nhánh trên phố Hollis. Dự án gồm hai giai đoạn thi công, tổng cộng sáu tháng.\n\nCông trình bắt đầu ngày 16 tháng 2 do công ty địa phương Benley Designs thực hiện. Một số khu vực của thư viện sẽ đóng cửa và sẽ có máy móc gây ồn hoạt động. Chúng tôi xin lỗi vì mọi bất tiện gây ra cho bạn đọc. Nếu bạn cần không gian yên tĩnh, các chi nhánh khác vẫn mở cửa theo giờ thường lệ.\n\nTrân trọng,\nDouglas Braun – Quản lý trưởng, Hệ thống Thư viện thành phố Webster","qs":[{"n":135,"opts":["to be created","to create","created","creating"],"ans":"B","xp":"Động từ. strive + to V (chủ động) = nỗ lực làm gì → (B) to create; phía sau có tân ngữ 'a comfortable environment' nên không dùng bị động (A)."},{"n":136,"opts":["out","except","for","beside"],"ans":"C","xp":"Giới từ. for + khoảng thời gian → 'for a total of six months' = trong tổng cộng sáu tháng → (C)."},{"n":137,"opts":["Our new selection of books is very popular.","Unfortunately, your card is no longer valid.","The library fines should be paid right away.","We regret any disturbances to patrons."],"ans":"D","xp":"Điền câu. Trước: một số khu đóng cửa, máy móc gây ồn; sau: nếu cần yên tĩnh hãy đến chi nhánh khác → câu giữa xin lỗi vì sự phiền toái → (D)."},{"n":138,"opts":["hours","statements","branches","sessions"],"ans":"A","xp":"Từ vựng. opening hours = giờ mở cửa → 'during their normal opening hours' (A). (C) branches 'chi nhánh' không đi với 'opening'."}]},{"ns":[139,142],"head":"Questions 139-142 refer to the following e-mail.","passage":"<div class=\"hdr\"><p><b>To:</b> stephenshaw@bvmail.com</p><p><b>From:</b> corrine@odinsalesconference.com</p><p><b>Date:</b> March 28</p><p><b>Subject:</b> Odin Sales Conference</p></div><p>Dear Mr. Shaw,</p><p>I would like to thank you for agreeing to be a presenter at the upcoming Odin Sales Conference. As one of our featured speakers, you <span class=\"blank\" data-n=\"139\">-------</span> an audience of over five thousand people in the main auditorium. There is a great deal of interest in the regulations surrounding imports and exports, so we'd like you to give a talk on the <span class=\"blank\" data-n=\"140\">-------</span> agencies that affect these activities.</p><p>To ensure that your digital files are compatible with our system, please send us an electronic copy of your presentation <span class=\"blank\" data-n=\"141\">-------</span> the conference on May 17. You should upload your handouts to our Web site rather than printing them out. <span class=\"blank\" data-n=\"142\">-------</span></p><p>Sincerely,<br>Corrine Roland</p>","vi":"Người nhận: stephenshaw@bvmail.com | Người gửi: corrine@odinsalesconference.com | Ngày: 28/3 | Chủ đề: Hội nghị Bán hàng Odin\n\nKính gửi ông Shaw,\n\nCảm ơn ông đã nhận lời làm diễn giả tại Hội nghị Bán hàng Odin sắp tới. Là một trong các diễn giả chính, ông sẽ nói chuyện trước hơn năm nghìn khán giả tại hội trường chính. Mọi người rất quan tâm đến các quy định về xuất nhập khẩu, nên chúng tôi muốn ông nói về các cơ quan quản lý có ảnh hưởng đến những hoạt động này.\n\nĐể chắc chắn tệp của ông tương thích với hệ thống của chúng tôi, vui lòng gửi bản điện tử bài thuyết trình trước hội nghị ngày 17 tháng 5. Ông nên tải tài liệu phát tay lên trang web thay vì in ra. Người tham dự sẽ tải tài liệu về trước.\n\nTrân trọng,\nCorrine Roland","qs":[{"n":139,"opts":["have addressed","addressed","have been addressed","will be addressing"],"ans":"D","xp":"Thì động từ. Hội nghị 'upcoming' (sắp tới) → tương lai (D) will be addressing 'sẽ nói chuyện với'. (A)(B) quá khứ/hoàn thành, (C) bị động sai nghĩa (có tân ngữ 'an audience')."},{"n":140,"opts":["regulatorily","regulatory","regulating","regulate"],"ans":"B","xp":"Từ loại. Giữa 'the' và danh từ 'agencies' cần tính từ → (B) regulatory; regulatory agencies = cơ quan quản lý. (A) trạng từ, (D) động từ, (C) V-ing không hợp nghĩa."},{"n":141,"opts":["behind","until","before","since"],"ans":"C","xp":"Giới từ. Gửi bản điện tử 'trước' hội nghị ngày 17/5 để kiểm tra tương thích → (C) before. (B) until 'cho đến khi' không hợp với hành động gửi một lần."},{"n":142,"opts":["We appreciate your creative suggestions.","The position should be filled as quickly as possible.","Our import business has grown substantially.","Participants will download the materials in advance."],"ans":"D","xp":"Điền câu. Trước: 'upload your handouts to our Web site rather than printing them out' → tiếp theo: 'Người tham dự sẽ tải tài liệu về trước' → (D)."}]},{"ns":[143,146],"head":"Questions 143-146 refer to the following letter.","passage":"<p>Valdez Insurance<br>4309 Holmes Street<br>Dallas, TX 75240</p><p>To Whom It May Concern:</p><p>I am writing this letter on behalf of Ana Robinson, who has recently applied for a sales position at your company. Ms. Robinson has <span class=\"blank\" data-n=\"143\">-------</span> as a senior sales associate at Hampton Industrial for the past three years. As a key member of our team, she handled a number of duties, from <span class=\"blank\" data-n=\"144\">-------</span> new clients to developing promotional materials. Ms. Robinson is a people person, and she has a natural talent for communication. Most of these <span class=\"blank\" data-n=\"145\">-------</span> will be perfect for your position, even though the field is different.</p><p>I would be happy to discuss Ms. Robinson's work performance in greater detail. <span class=\"blank\" data-n=\"146\">-------</span> My phone extension from the main switchboard, which is listed below, is 35.</p><p>Sincerely,<br>Maria Yokota<br>Sales Director, Hampton Industrial<br>469-555-6489</p>","vi":"Valdez Insurance – 4309 phố Holmes, Dallas, TX 75240\n\nKính gửi Quý công ty,\n\nTôi viết thư này thay cho Ana Robinson, người vừa ứng tuyển vị trí bán hàng tại công ty quý vị. Cô Robinson đã làm nhân viên bán hàng cấp cao tại Hampton Industrial trong ba năm qua. Là thành viên chủ chốt của nhóm, cô đảm nhận nhiều việc, từ thu hút khách hàng mới đến xây dựng tài liệu quảng bá. Cô Robinson rất giỏi giao tiếp với mọi người và có năng khiếu giao tiếp bẩm sinh. Hầu hết những kỹ năng này sẽ rất phù hợp với vị trí của quý vị, dù lĩnh vực khác nhau.\n\nTôi rất sẵn lòng trao đổi chi tiết hơn về kết quả làm việc của cô Robinson. Xin cứ liên hệ với tôi tại văn phòng. Số máy lẻ của tôi qua tổng đài chính (ghi bên dưới) là 35.\n\nTrân trọng,\nMaria Yokota – Giám đốc kinh doanh, Hampton Industrial – 469-555-6489","qs":[{"n":143,"opts":["accomplished","served","recognized","applied"],"ans":"B","xp":"Từ vựng. serve as + chức vụ = làm (vị trí) → 'has served as a senior sales associate' (B). (A) accomplished cần tân ngữ, (C) recognized 'được công nhận' cần bị động, (D) applied 'ứng tuyển' (for)."},{"n":144,"opts":["having attracted","attracted","attracting","attracts"],"ans":"C","xp":"Cấu trúc song song. from A to B: 'from ------- new clients to developing promotional materials' → song song với 'developing' cần V-ing (C) attracting. (A) V-ing hoàn thành không hợp, (B)(D) động từ chia."},{"n":145,"opts":["changes","agreements","skills","concerns"],"ans":"C","xp":"Từ vựng. Câu trước nói về khả năng giao tiếp, năng khiếu → 'these skills' (những kỹ năng này) → (C)."},{"n":146,"opts":["She will review the application for the job.","I will invite you to the next round of interviews.","She will give you an update with more precise data.","Please feel free to contact me at my office."],"ans":"D","xp":"Điền câu. Trước: 'I would be happy to discuss... in greater detail'; sau: 'My phone extension... is 35' → câu giữa mời liên hệ: (D) 'Xin cứ liên hệ với tôi tại văn phòng'."}]}],"p7":[{"ns":[147,148],"head":"Questions 147-148 refer to the following coupon.","passages":["<h3>RDC</h3><h4>Ideas in Motion</h4><p><b>15% off your visit: 15% admission discount</b></p><p>This coupon is valid at RDC for 15% off admission for up to four people. There is no expiration date, but the coupon cannot be combined with other discounts. Visitors are permitted access to all displays, hands-on lab activities, and biology lectures (view our Web site for the lecture schedule).</p><p>Summer Hours (June-August): Mon.-Sat., 9 A.M.-7 P.M.<br>Standard Hours (September-May): Tues.-Sun., 11 A.M.-7 P.M.</p>"],"vi":"RDC – Ý tưởng chuyển động\n\nGiảm 15% cho chuyến tham quan: giảm 15% vé vào cửa\nPhiếu này dùng tại RDC để giảm 15% vé vào cửa cho tối đa bốn người. Phiếu không có hạn sử dụng nhưng không dùng chung với ưu đãi khác. Khách được vào xem mọi khu trưng bày, tham gia hoạt động thực hành trong phòng thí nghiệm và nghe các bài giảng sinh học (xem lịch bài giảng trên trang web).\nGiờ mùa hè (tháng 6–8): thứ Hai–thứ Bảy, 9 giờ sáng – 7 giờ tối.\nGiờ thường (tháng 9–5): thứ Ba–Chủ Nhật, 11 giờ sáng – 7 giờ tối.","qs":[{"n":147,"q":"What most likely is RDC?","qvi":"RDC nhiều khả năng là gì?","opts":["A movie theater","A utility company","A science center","A department store"],"ans":"C","xp":"'all displays, hands-on lab activities, and biology lectures' → trung tâm khoa học → (C)."},{"n":148,"q":"What is true about RDC in September?","qvi":"Điều gì đúng về RDC vào tháng 9?","opts":["It has an earlier closing time.","It is closed in the mornings.","It is open for more days.","It is open for fewer hours."],"ans":"D","xp":"Tháng 9 theo giờ thường: 11 giờ sáng – 7 giờ tối (8 tiếng/ngày), ít hơn giờ mùa hè 9 giờ – 7 giờ (10 tiếng) → mở ít giờ hơn → (D). (A) giờ đóng cửa vẫn là 7 giờ; (C) số ngày vẫn là 6 ngày/tuần."}]},{"ns":[149,150],"head":"Questions 149-150 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> bruce_garmon@writersunite.com</p><p><b>From:</b> reneevarney@alabasterediting.com</p><p><b>Date:</b> October 3</p><p><b>Subject:</b> Writers Unite Newsletter</p></div><p>Dear Mr. Garmon,</p><p>I have been a subscriber to the Writers Unite monthly newsletter for about three years. I look forward to receiving it every month, as it always provides an extensive index of companies that are currently hiring freelancers. In fact, it has helped me to find several projects, so I'm thankful to have such a useful resource.</p><p>I sometimes read the featured articles, but it does seem that there are several potential topics that have not been covered since I started receiving the publication. Do you accept suggestions for upcoming newsletters? If so, here's what I was thinking:</p><ul><li>Writing a Book Proposal</li><li>Tips for Overcoming Writer's Block</li></ul><p>Thanks for all the help you've given to me and other freelancers!</p><p>Sincerely,<br>Renée Varney</p>"],"vi":"Người nhận: Bruce Garmon | Người gửi: Renée Varney | Ngày: 3/10 | Chủ đề: Bản tin Writers Unite\n\nKính gửi ông Garmon,\n\nTôi đã đăng ký nhận bản tin hằng tháng Writers Unite khoảng ba năm nay. Tháng nào tôi cũng mong nhận bản tin, vì bản tin luôn có danh sách đầy đủ các công ty đang thuê người làm tự do. Thật ra, nhờ bản tin mà tôi đã tìm được vài dự án, nên tôi rất biết ơn khi có nguồn thông tin hữu ích như vậy.\n\nThỉnh thoảng tôi đọc các bài viết nổi bật, nhưng có vẻ có vài chủ đề tiềm năng chưa được đề cập từ khi tôi bắt đầu nhận bản tin. Ông có nhận góp ý cho các số sắp tới không? Nếu có, đây là những gì tôi nghĩ đến:\n- Viết đề xuất xuất bản sách\n- Mẹo vượt qua tình trạng bí ý tưởng khi viết\n\nCảm ơn ông vì mọi sự giúp đỡ dành cho tôi và những người làm tự do khác!\nTrân trọng, Renée Varney","qs":[{"n":149,"q":"What aspect of the monthly newsletter does Ms. Varney praise?","qvi":"Bà Varney khen điểm nào của bản tin hằng tháng?","opts":["Its project management tips","Its easy search features","Its list of job opportunities","Its information about discounts"],"ans":"C","xp":"'it always provides an extensive index of companies that are currently hiring freelancers... it has helped me to find several projects' → danh sách cơ hội việc làm → (C)."},{"n":150,"q":"What does Ms. Varney point out in the e-mail?","qvi":"Bà Varney nêu điều gì trong e-mail?","opts":["Posts that she forwarded to others","Subjects that she thinks need attention","Articles that contained inaccuracies","Policies that need to be changed"],"ans":"B","xp":"'there are several potential topics that have not been covered' rồi đề xuất hai chủ đề → (B)."}]},{"ns":[151,152],"head":"Questions 151-152 refer to the following text-message chain.","passages":["<div class=\"msg\"><p><b>Shirley Campbell (10:33 A.M.)</b></p><p>I've just dropped off the boxes of the Summer Breeze perfume at the South Bend store. I have three boxes for your branch in Oakland. When does your shift end?</p></div><div class=\"msg\"><p><b>Chiara Feliciano (10:35 A.M.)</b></p><p>I've just started, so feel free to stop by anytime before we close.</p></div><div class=\"msg\"><p><b>Shirley Campbell (10:36 A.M.)</b></p><p>OK. The South Bend branch did a great job setting up the display for the perfume. They decorated the display area with beach towels, beach balls, and colorful balloons.</p></div><div class=\"msg\"><p><b>Chiara Feliciano (10:37 A.M.)</b></p><p>That sounds exactly like us. Will you need help unloading the items?</p></div><div class=\"msg\"><p><b>Shirley Campbell (10:38 A.M.)</b></p><p>Yes, so please send someone out when I arrive. I'll text you then.</p></div>"],"vi":"Shirley Campbell (10:33): Tôi vừa giao các thùng nước hoa Summer Breeze ở cửa hàng South Bend. Tôi có ba thùng cho chi nhánh Oakland của chị. Ca của chị kết thúc lúc mấy giờ?\nChiara Feliciano (10:35): Tôi vừa bắt đầu ca, nên chị cứ ghé lúc nào cũng được trước giờ đóng cửa.\nShirley Campbell (10:36): Được. Chi nhánh South Bend trang trí kệ trưng bày nước hoa rất đẹp. Họ trang trí khu trưng bày bằng khăn tắm biển, bóng bãi biển và bóng bay nhiều màu.\nChiara Feliciano (10:37): Nghe y hệt chỗ chúng tôi. Chị có cần người giúp dỡ hàng không?\nShirley Campbell (10:38): Có, khi tôi đến chị cho người ra giúp nhé. Lúc đó tôi sẽ nhắn chị.","qs":[{"n":151,"q":"Why did Ms. Campbell send a message to Ms. Feliciano?","qvi":"Vì sao cô Campbell nhắn tin cho cô Feliciano?","opts":["To confirm a delivery of goods","To inquire about a new product","To schedule a time for a demonstration","To get directions to the South Bend store"],"ans":"A","xp":"'I have three boxes for your branch in Oakland. When does your shift end?' → xác nhận việc giao hàng → (A)."},{"n":152,"q":"At 10:37 A.M., what does Ms. Feliciano suggest when she writes, \"That sounds exactly like us\"?","qvi":"Lúc 10:37, cô Feliciano ngụ ý gì khi viết \"Nghe y hệt chỗ chúng tôi\"?","opts":["Oakland has similar sales figures to South Bend.","Ms. Feliciano will get advice from the South Bend manager.","Some decorations have been set up in Oakland.","Ms. Campbell can purchase the towels she requested."],"ans":"C","xp":"Cô Campbell kể South Bend trang trí bằng khăn biển, bóng, bóng bay; cô Feliciano nói 'y hệt chỗ chúng tôi' → chi nhánh Oakland cũng đã trang trí như vậy → (C)."}]},{"ns":[153,155],"head":"Questions 153-155 refer to the following report.","passages":["<h3>Houghton Construction</h3><table><tr><td>Customer:</td><td>Cecilia Irwin</td></tr><tr><td>Address:</td><td>429 Jaksa Lane, Baltimore, MD 21202</td></tr><tr><td>Shingle/Tile Type:</td><td>Slate</td></tr><tr><td>Date of Visit:</td><td>September 29</td></tr><tr><td>Time Since Last Visit:</td><td>1 year</td></tr><tr><td>Houghton Representative:</td><td>Andrew Lahti</td></tr></table><table><tr><th>Roof Features</th><th>Grade</th></tr><tr><td>Shingles</td><td>3</td></tr><tr><td>Tiles</td><td>0</td></tr><tr><td>Gutters</td><td>4</td></tr><tr><td>Drainpipe</td><td>1</td></tr><tr><td>Roof deck</td><td>2</td></tr><tr><td>Solar panels</td><td>0</td></tr><tr><td>Chimney (including seal)</td><td>3</td></tr></table><p><b>Representative's Comments:</b> I recommended ordering more slate tiles for storage, as the particular version in use will be discontinued soon. Awaiting customer approval.</p><p><b>Grade Descriptions:</b> 0: Not present / 1: Excellent: No action needed / 2: Minor deterioration: Recheck in one year / 3: Medium deterioration: Recheck in six months / 4: Major deterioration: Replace within three to six months / 5: Severe deterioration: Replace immediately</p>"],"vi":"Houghton Construction – Báo cáo kiểm tra mái nhà\n\nKhách hàng: Cecilia Irwin | Địa chỉ: 429 Jaksa Lane, Baltimore | Loại ngói: đá phiến | Ngày đến: 29/9 | Thời gian từ lần trước: 1 năm | Nhân viên: Andrew Lahti\n\nHạng mục – Điểm: tấm lợp 3 | ngói 0 | máng xối 4 | ống thoát nước 1 | sàn mái 2 | tấm pin mặt trời 0 | ống khói (gồm phần trám) 3\n\nNhận xét của nhân viên: Tôi đã khuyên đặt thêm ngói đá phiến để dự trữ, vì loại đang dùng sắp ngừng sản xuất. Đang chờ khách hàng đồng ý.\n\nÝ nghĩa điểm: 0: Không có / 1: Rất tốt, không cần làm gì / 2: Xuống cấp nhẹ, kiểm tra lại sau 1 năm / 3: Xuống cấp vừa, kiểm tra lại sau 6 tháng / 4: Xuống cấp nặng, thay trong 3–6 tháng / 5: Xuống cấp nghiêm trọng, thay ngay.","qs":[{"n":153,"q":"What did Mr. Lahti most likely do on September 29?","qvi":"Ngày 29/9 ông Lahti nhiều khả năng đã làm gì?","opts":["Placed an order","Assessed a roof's condition","Repaired some components","Delivered a shipment"],"ans":"B","xp":"Báo cáo chấm điểm tình trạng từng bộ phận mái nhà vào 'Date of Visit: September 29' → ông kiểm tra, đánh giá mái nhà → (B). (A) việc đặt ngói còn 'Awaiting customer approval'."},{"n":154,"q":"What feature should be replaced the soonest?","qvi":"Bộ phận nào nên được thay sớm nhất?","opts":["Shingles","Gutters","Drainpipe","Roof deck"],"ans":"B","xp":"Điểm cao nhất là Gutters 4 = 'Major deterioration: Replace within three to six months'; không có mục nào điểm 5 → máng xối → (B)."},{"n":155,"q":"What is implied about Ms. Irwin's roof?","qvi":"Có thể suy ra điều gì về mái nhà của bà Irwin?","opts":["It was originally installed by an amateur.","It will be replaced immediately.","Its chimney edges were resealed in September.","It is not equipped to generate energy from the sun."],"ans":"D","xp":"'Solar panels: 0' và 0 = 'Not present' → mái nhà không có tấm pin mặt trời → (D)."}]},{"ns":[156,157],"head":"Questions 156-157 refer to the following information.","passages":["<h3>Logan Community Center</h3><h4>4-week classes beginning the week of August 10th</h4><p><b>DIY Marketing</b><br>Learn the basics of promoting your business without spending a lot of money to hire experts.</p><table><tr><th>Enrollment #</th><th>Instructor</th><th>Day/Time</th><th>Location</th></tr><tr><td>839586-01</td><td>Patricia DeRosa</td><td>Mondays/6-8 P.M.</td><td>Room 103</td></tr><tr><td>839586-02</td><td>Stewart Crompton</td><td>Thursdays/1-3 P.M.</td><td>Room 206</td></tr></table><p><b>Knowing Your Audience</b><br>Learn to make the most of your next speech by tailoring your comments to the audience.</p><table><tr><th>Enrollment #</th><th>Instructor</th><th>Day/Time</th><th>Location</th></tr><tr><td>842771-01</td><td>Patricia DeRosa</td><td>Thursdays/2-4 P.M.</td><td>Room 205</td></tr><tr><td>842771-02</td><td>Abhinav Patel</td><td>Saturdays/9-11 A.M.</td><td>Room 102</td></tr></table>"],"vi":"Trung tâm cộng đồng Logan – Các lớp 4 tuần bắt đầu từ tuần 10/8\n\nTự làm marketing: Học những điều cơ bản để quảng bá doanh nghiệp mà không tốn nhiều tiền thuê chuyên gia.\n839586-01: Patricia DeRosa – thứ Hai, 6–8 giờ tối – phòng 103 | 839586-02: Stewart Crompton – thứ Năm, 1–3 giờ chiều – phòng 206\n\nHiểu khán giả của bạn: Học cách tận dụng tốt nhất bài phát biểu tiếp theo bằng cách điều chỉnh lời nói cho hợp với khán giả.\n842771-01: Patricia DeRosa – thứ Năm, 2–4 giờ chiều – phòng 205 | 842771-02: Abhinav Patel – thứ Bảy, 9–11 giờ sáng – phòng 102","qs":[{"n":156,"q":"What is true about Ms. DeRosa?","qvi":"Điều gì đúng về cô DeRosa?","opts":["She teaches two days a week.","She is a financial expert.","She was hired by Mr. Crompton.","She operates her own business."],"ans":"A","xp":"Cô DeRosa dạy lớp DIY Marketing thứ Hai và lớp Knowing Your Audience thứ Năm → dạy hai ngày mỗi tuần → (A)."},{"n":157,"q":"Why might people sign up for Mr. Patel's course?","qvi":"Vì sao người ta có thể đăng ký lớp của ông Patel?","opts":["To improve public speaking skills","To get advice on basic laws","To learn how to analyze comments","To practice making advertisements"],"ans":"A","xp":"Ông Patel dạy 'Knowing Your Audience': 'make the most of your next speech by tailoring your comments to the audience' → cải thiện kỹ năng nói trước công chúng → (A)."}]},{"ns":[158,160],"head":"Questions 158-160 refer to the following e-mail.","passages":["<div class=\"hdr\"><p><b>To:</b> Muldoon Enterprises Employees</p><p><b>From:</b> Navin Kamath</p><p><b>Date:</b> February 20</p><p><b>Subject:</b> Please note</p></div><p>Dear Muldoon Enterprises Employees,</p><p>As discussed in the most recent staff meeting, the human resources department has made a change to the vacation policy. <span class=\"pos\">[1]</span> From now on, a maximum of three people can be absent from a department at any given time. We hope this will help us to maintain a high level of productivity and customer service. <span class=\"pos\">[2]</span> An up-to-date calendar of planned absences is available on our company Web site, so that should be checked first. You should also talk to your colleagues about their vacation plans. <span class=\"pos\">[3]</span></p><p>As you can only request vacation time up to four months in advance, you may want to consider downloading the EZ-Cal smartphone app. <span class=\"pos\">[4]</span> You can set it to remind you to request vacation time on a certain date.</p><p>Thank you for your cooperation.</p><p>Sincerely,<br>Navin Kamath<br>HR Director, Muldoon Enterprises</p>"],"vi":"Người nhận: Nhân viên Muldoon Enterprises | Người gửi: Navin Kamath | Ngày: 20/2 | Chủ đề: Xin lưu ý\n\nGửi toàn thể nhân viên Muldoon Enterprises,\n\nNhư đã bàn trong buổi họp nhân viên gần nhất, phòng nhân sự đã thay đổi chính sách nghỉ phép. Từ nay, mỗi phòng ban chỉ được tối đa ba người nghỉ cùng một lúc. Chúng tôi hy vọng điều này giúp duy trì năng suất và chất lượng phục vụ khách hàng cao. Lịch nghỉ phép dự kiến được cập nhật trên trang web công ty, nên hãy xem lịch đó trước. Bạn cũng nên trao đổi với đồng nghiệp về kế hoạch nghỉ của họ. Hãy làm những bước này để đơn xin nghỉ của bạn không bị từ chối.\n\nVì bạn chỉ có thể xin nghỉ trước tối đa bốn tháng, bạn có thể cân nhắc tải ứng dụng điện thoại EZ-Cal. Bạn có thể cài để ứng dụng nhắc bạn xin nghỉ vào một ngày nhất định.\n\nCảm ơn sự hợp tác của các bạn.\nNavin Kamath – Giám đốc nhân sự, Muldoon Enterprises","qs":[{"n":158,"q":"What is suggested about Muldoon Enterprises?","qvi":"Có thể suy ra điều gì về Muldoon Enterprises?","opts":["It will no longer offer paid vacation days to employees.","It will restrict the conditions for taking time off.","It will give bonuses to employees who don't miss work days.","It will e-mail staff members updates to the vacation calendar."],"ans":"B","xp":"'a maximum of three people can be absent from a department at any given time' → hạn chế điều kiện nghỉ phép → (B). (D) lịch có trên trang web, không gửi qua e-mail."},{"n":159,"q":"According to Mr. Kamath, what can the EZ-Cal smartphone application do?","qvi":"Theo ông Kamath, ứng dụng EZ-Cal làm được gì?","opts":["Share messages between employees","Track the amount of time spent working","Schedule meetings on short notice","Send a reminder about a task"],"ans":"D","xp":"'You can set it to remind you to request vacation time on a certain date' → gửi lời nhắc → (D)."},{"n":160,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"Please take these measures to ensure that your application is not rejected.\"","qvi":"Câu sau phù hợp nhất ở vị trí nào? \"Hãy làm những bước này để đơn xin nghỉ của bạn không bị từ chối.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"C","xp":"'these measures' chỉ các bước vừa nêu: xem lịch nghỉ trên web trước và trao đổi với đồng nghiệp → đặt sau các bước này, vị trí [3] → (C)."}]},{"ns":[161,163],"head":"Questions 161-163 refer to the following article.","passages":["<h3>Vaka Sees Business Boom</h3><p>Sales at Vaka Tech have increased by over 200% compared to the same period last year, mainly driven by its popular Spirex-80 device. Earlier this year, the EU added strict regulations on bottled water, limiting the mineral content far below the previous threshold. Many beverage companies were forced to use additional finances to bring their products into compliance.</p><p>The change was announced in early March. From that point, sales of the Spirex-80—a system that effectively purifies water—skyrocketed. Offering a solution that all beverage companies need, the Spirex-80 certainly seems to be in the right place at the right time.</p>"],"vi":"Vaka làm ăn bùng nổ\n\nDoanh số của Vaka Tech tăng hơn 200% so với cùng kỳ năm ngoái, chủ yếu nhờ thiết bị Spirex-80 được ưa chuộng. Đầu năm nay, EU đưa ra quy định nghiêm ngặt về nước đóng chai, giới hạn hàm lượng khoáng chất thấp hơn nhiều so với ngưỡng cũ. Nhiều công ty đồ uống buộc phải chi thêm tiền để sản phẩm đạt chuẩn.\n\nThay đổi được công bố vào đầu tháng 3. Từ thời điểm đó, doanh số Spirex-80 – hệ thống lọc nước hiệu quả – tăng vọt. Mang đến giải pháp mà mọi công ty đồ uống đều cần, Spirex-80 rõ ràng xuất hiện đúng nơi, đúng lúc.","qs":[{"n":161,"q":"According to the article, what has increased costs for beverage companies?","qvi":"Theo bài báo, điều gì làm tăng chi phí của các công ty đồ uống?","opts":["New government regulations","A shortage of ingredients","Wage payments for staff","Rising fuel prices"],"ans":"A","xp":"'the EU added strict regulations on bottled water... Many beverage companies were forced to use additional finances' → quy định mới → (A)."},{"n":162,"q":"The word \"point\" in paragraph 2, line 1, is closest in meaning to","qvi":"Từ \"point\" ở đoạn 2, dòng 1 gần nghĩa nhất với","opts":["location","detail","instant","purpose"],"ans":"C","xp":"'From that point' = từ thời điểm đó → (C) instant 'thời điểm, khoảnh khắc'. (A) location là nghĩa 'điểm (nơi chốn)', không hợp."},{"n":163,"q":"What does the article indicate that Vaka Tech has done?","qvi":"Bài báo cho biết Vaka Tech đã làm gì?","opts":["Changed the design of the Spirex-80","Moved to a country in Europe","Taken over one of its competitors","Created a purification system"],"ans":"D","xp":"'the Spirex-80—a system that effectively purifies water' → (D)."}]},{"ns":[164,167],"head":"Questions 164-167 refer to the following online chat discussion.","passages":["<div class=\"msg\"><p><b>Kirby Auyer (9:08 A.M.)</b></p><p>Hi, Deandra and Paola. Could we review the résumés for the tax compliance officer position sometime in the afternoon instead of at 10? I need to cover Mr. Hong's presentation at the board meeting.</p></div><div class=\"msg\"><p><b>Deandra Calteaux (9:09 A.M.)</b></p><p>How about 3 P.M.? We could get together in the meeting room to go over everything.</p></div><div class=\"msg\"><p><b>Paola Gomez (9:10 A.M.)</b></p><p>That works perfectly for me. I'm still working on a report that's due at 1 P.M.</p></div><div class=\"msg\"><p><b>Kirby Auyer (9:10 A.M.)</b></p><p>That'll be a problem. According to the online schedule, the IT team will be in there all day for their quarterly training.</p></div><div class=\"msg\"><p><b>Deandra Calteaux (9:11 A.M.)</b></p><p>We could meet in the employee lounge. It's usually empty.</p></div><div class=\"msg\"><p><b>Paola Gomez (9:12 A.M.)</b></p><p>OK. Should I bring my laptop so I can look at the electronic versions of the files?</p></div><div class=\"msg\"><p><b>Deandra Calteaux (9:13 A.M.)</b></p><p>That's not necessary. I'll print paper copies for everyone.</p></div><div class=\"msg\"><p><b>Kirby Auyer (9:14 A.M.)</b></p><p>See you then. Thanks for accommodating me.</p></div>"],"vi":"Kirby Auyer (9:08): Chào Deandra và Paola. Mình xem hồ sơ ứng viên vị trí chuyên viên tuân thủ thuế vào buổi chiều thay vì lúc 10 giờ được không? Tôi phải thuyết trình thay ông Hong ở cuộc họp hội đồng quản trị.\nDeandra Calteaux (9:09): 3 giờ chiều thì sao? Mình có thể gặp ở phòng họp để xem hết.\nPaola Gomez (9:10): Giờ đó rất hợp với tôi. Tôi vẫn đang làm báo cáo hạn 1 giờ chiều.\nKirby Auyer (9:10): Thế thì có vấn đề. Theo lịch trực tuyến, nhóm IT sẽ dùng phòng đó cả ngày để đào tạo hằng quý.\nDeandra Calteaux (9:11): Mình có thể gặp ở phòng nghỉ nhân viên. Ở đó thường không có ai.\nPaola Gomez (9:12): Được. Tôi có nên mang laptop để xem bản điện tử của hồ sơ không?\nDeandra Calteaux (9:13): Không cần đâu. Tôi sẽ in bản giấy cho mọi người.\nKirby Auyer (9:14): Hẹn gặp lúc đó. Cảm ơn mọi người đã sắp xếp giúp tôi.","qs":[{"n":164,"q":"Why is Mr. Auyer busy in the morning?","qvi":"Vì sao buổi sáng ông Auyer bận?","opts":["He will give board members a tour.","He has to give a talk in place of a colleague.","He must visit another branch.","He has an urgent report to complete."],"ans":"B","xp":"'I need to cover Mr. Hong's presentation at the board meeting' → thuyết trình thay đồng nghiệp → (B). (D) người làm báo cáo là Paola."},{"n":165,"q":"Why does Ms. Calteaux think they should meet in the employee lounge?","qvi":"Vì sao cô Calteaux nghĩ nên gặp ở phòng nghỉ nhân viên?","opts":["Because the meeting room will be in use","Because food is allowed in the area","Because it is nearest to Mr. Auyer's office","Because it has extra space for visitors"],"ans":"A","xp":"Ông Auyer nói nhóm IT dùng phòng họp cả ngày; cô liền đề xuất phòng nghỉ nhân viên → (A)."},{"n":166,"q":"At 9:13 A.M., what does Ms. Calteaux suggest when she writes, \"That's not necessary\"?","qvi":"Lúc 9:13, cô Calteaux ngụ ý gì khi viết \"Không cần đâu\"?","opts":["Mr. Auyer does not have to help with a project.","He has already contacted some job candidates.","Ms. Gomez will not need to use a laptop.","Ms. Gomez should not review the files in advance."],"ans":"C","xp":"Paola hỏi có nên mang laptop không; cô đáp không cần vì 'I'll print paper copies for everyone' → (C)."},{"n":167,"q":"When will the writers meet today?","qvi":"Hôm nay họ sẽ gặp lúc mấy giờ?","opts":["At 10:00 A.M.","At 1:00 P.M.","At 3:00 P.M.","At 4:00 P.M."],"ans":"C","xp":"'How about 3 P.M.?' – 'That works perfectly for me' – chỉ đổi địa điểm, không đổi giờ → (C). (A) giờ cũ, (B) hạn nộp báo cáo."}]},{"ns":[168,171],"head":"Questions 168-171 refer to the following letter.","passages":["<p>Brian Streich<br>502 Carissa Avenue<br>Aberdeen, SD 57401</p><p>April 3</p><p>Dear Mr. Streich,</p><p>I recently met with a colleague of mine who is in charge of the Community Outreach Contest to promote quality-of-life improvements. Based on the ideas you presented at our last Millennial Leaders Club meeting, I believe that you would be an excellent fit for this event. Your program of relaxation techniques for reducing stress and preventing illness is sure to impress the judging panel.</p><p>If you are interested, you must provide a 300-word description of your program and how it can help others. You easily meet the entry criteria, so I believe you would definitely make it past the screening phase. After that, you would be invited to give a brief talk about your program and answer questions. The winner will receive a cash prize of $5,000, so I think it's definitely worth giving it a try.</p><p>I've taken the liberty of downloading and printing the application form, which you will find enclosed. You must complete and send it, along with your program description and a copy of your passport or driver's license for identification purposes, no later than April 30.</p><p>Warmest regards,<br>Elaina Urmanski</p>"],"vi":"Gửi ông Brian Streich, 502 Carissa Avenue, Aberdeen – ngày 3/4\n\nKính gửi ông Streich,\n\nGần đây tôi gặp một đồng nghiệp phụ trách Cuộc thi Hướng về Cộng đồng nhằm thúc đẩy nâng cao chất lượng cuộc sống. Dựa trên những ý tưởng ông trình bày ở buổi họp gần nhất của Câu lạc bộ Lãnh đạo Thế hệ Millennial, tôi tin ông rất phù hợp với cuộc thi này. Chương trình các kỹ thuật thư giãn giúp giảm căng thẳng và phòng bệnh của ông chắc chắn sẽ gây ấn tượng với ban giám khảo.\n\nNếu quan tâm, ông cần gửi bản mô tả 300 từ về chương trình và cách nó giúp ích cho người khác. Ông dễ dàng đáp ứng tiêu chí tham gia, nên tôi tin ông chắc chắn sẽ qua vòng sơ loại. Sau đó, ông sẽ được mời trình bày ngắn về chương trình và trả lời câu hỏi. Người thắng cuộc nhận giải thưởng 5.000 đô, nên tôi nghĩ rất đáng thử.\n\nTôi đã tự ý tải và in mẫu đơn đăng ký, gửi kèm thư này. Ông cần điền và gửi mẫu đơn cùng bản mô tả chương trình và bản sao hộ chiếu hoặc bằng lái xe để xác minh danh tính, chậm nhất ngày 30/4.\n\nTrân trọng,\nElaina Urmanski","qs":[{"n":168,"q":"Why did Ms. Urmanski send the letter?","qvi":"Vì sao bà Urmanski gửi thư?","opts":["To suggest entering a competition","To recruit a judge for a panel","To extend an invitation to join a club","To inform Mr. Streich of a job opening"],"ans":"A","xp":"Bà giới thiệu Community Outreach Contest, 'you would be an excellent fit for this event... definitely worth giving it a try' → gợi ý ông dự thi → (A)."},{"n":169,"q":"What most likely is Mr. Streich's field of expertise?","qvi":"Lĩnh vực chuyên môn của ông Streich nhiều khả năng là gì?","opts":["Investing","Technology","Health","Manufacturing"],"ans":"C","xp":"'Your program of relaxation techniques for reducing stress and preventing illness' → sức khỏe → (C)."},{"n":170,"q":"The word \"meet\" in paragraph 2, line 2, is closest in meaning to","qvi":"Từ \"meet\" ở đoạn 2, dòng 2 gần nghĩa nhất với","opts":["collect","greet","sustain","fulfill"],"ans":"D","xp":"'meet the entry criteria' = đáp ứng tiêu chí → (D) fulfill. (B) greet là nghĩa 'gặp, chào', không hợp."},{"n":171,"q":"What should Mr. Streich do by April 30?","qvi":"Ông Streich nên làm gì trước ngày 30/4?","opts":["Download a form","Submit the required documents","Respond to questions","Renew a passport"],"ans":"B","xp":"'You must complete and send it (mẫu đơn), along with your program description and a copy of your passport or driver's license... no later than April 30' → nộp các giấy tờ cần thiết → (B). (A) bà đã tải giúp rồi."}]},{"ns":[172,175],"head":"Questions 172-175 refer to the following article.","passages":["<p>*Surabaya Herald*<br>March 24</p><p>The number of new Internet customers in Indonesia is nearly three times that of other countries over the same one-year period. Competition among Internet service providers has heated up as more and more people, especially in rural communities, come online. <span class=\"pos\">[1]</span></p><p>Lumbra Communication has been a long-time provider of Internet services, focusing mainly on major cities. It used to be the only option for Internet users in many places, but that is changing. <span class=\"pos\">[2]</span> As a result, most new customers are not first-time Internet users, but rather transferred customers from other companies.</p><p>With so many companies to choose from, customers no longer put up with long periods of downtime. If customers cannot rely on a stable connection, they simply change to another provider. This is what caused the downfall of Dhanas Web, which went out of business two months ago after previously holding the second highest amount of market share. <span class=\"pos\">[3]</span></p><p>Lumbra Communication still leads the market, but Sandang Tech is gaining ground. <span class=\"pos\">[4]</span> Sandang Tech has only been in operation for eighteen months, but it is grabbing the attention of consumers through its phone and Internet packages. It works continually to provide faster Internet speeds, which is particularly important to those who use the Internet for video streaming. Sandang Tech's focus is on young professionals, and it hopes to make them lifelong customers. It also has a reputation for making same-day repairs to broken lines and routers. A smart and adaptable business model may be the key to maximizing the surge in Internet usage.</p>"],"vi":"Surabaya Herald – ngày 24/3\n\nSố khách hàng Internet mới ở Indonesia gần gấp ba các nước khác trong cùng khoảng thời gian một năm. Cạnh tranh giữa các nhà cung cấp dịch vụ Internet ngày càng gay gắt khi ngày càng nhiều người, nhất là ở nông thôn, bắt đầu dùng Internet.\n\nLumbra Communication là nhà cung cấp Internet lâu năm, chủ yếu tập trung ở các thành phố lớn. Trước đây đây là lựa chọn duy nhất ở nhiều nơi, nhưng điều đó đang thay đổi. Lượng khách hàng dự kiến sẽ bắt đầu thu hẹp do thị trường đã bão hòa. Vì vậy, phần lớn khách hàng mới không phải người lần đầu dùng Internet, mà là khách chuyển từ công ty khác sang.\n\nCó quá nhiều công ty để chọn, khách hàng không còn chịu đựng việc mất kết nối lâu. Nếu không có kết nối ổn định, họ chỉ việc đổi nhà cung cấp. Đây là nguyên nhân khiến Dhanas Web sụp đổ – công ty này đóng cửa hai tháng trước dù từng có thị phần lớn thứ hai.\n\nLumbra Communication vẫn dẫn đầu thị trường, nhưng Sandang Tech đang bắt kịp. Sandang Tech mới hoạt động được 18 tháng nhưng đang thu hút người tiêu dùng bằng các gói điện thoại và Internet. Công ty liên tục nâng tốc độ Internet, điều đặc biệt quan trọng với người xem video trực tuyến. Sandang Tech tập trung vào giới trẻ đi làm và mong biến họ thành khách hàng trọn đời. Công ty còn nổi tiếng sửa đường dây và bộ định tuyến hỏng ngay trong ngày. Một mô hình kinh doanh thông minh và linh hoạt có thể là chìa khóa để tận dụng tối đa sự bùng nổ sử dụng Internet.","qs":[{"n":172,"q":"What is the main topic of the article?","qvi":"Chủ đề chính của bài báo là gì?","opts":["The popularity of Internet-based businesses","The most common marketing methods","The rapid growth of an industry","The best companies to work for in Indonesia"],"ans":"C","xp":"Bài báo nói số khách hàng Internet mới tăng mạnh và cạnh tranh giữa các nhà cung cấp Internet → sự phát triển nhanh của ngành dịch vụ Internet → (C)."},{"n":173,"q":"What is implied about Dhanas Web?","qvi":"Có thể suy ra điều gì về Dhanas Web?","opts":["Its prices were too high.","Its main business was phone packages.","It was the area's longest-running business.","It had unreliable service."],"ans":"D","xp":"'If customers cannot rely on a stable connection, they simply change to another provider. This is what caused the downfall of Dhanas Web' → dịch vụ không ổn định → (D)."},{"n":174,"q":"What is NOT indicated as a strategy of Sandang Tech?","qvi":"Điều gì KHÔNG được nêu là chiến lược của Sandang Tech?","opts":["Offering a video streaming service","Targeting young consumers","Increasing its Internet speed","Resolving technical issues quickly"],"ans":"A","xp":"(B) 'focus is on young professionals'; (C) 'provide faster Internet speeds'; (D) 'same-day repairs'. Bài chỉ nói tốc độ quan trọng với người xem video, không nói công ty cung cấp dịch vụ xem video → (A)."},{"n":175,"q":"In which of the positions marked [1], [2], [3], and [4] does the following sentence best belong? \"The customer pool is expected to start shrinking due to the high market saturation.\"","qvi":"Câu sau phù hợp nhất ở vị trí nào? \"Lượng khách hàng dự kiến sẽ bắt đầu thu hẹp do thị trường đã bão hòa.\"","opts":["[1]","[2]","[3]","[4]"],"ans":"B","xp":"Câu sau vị trí [2]: 'As a result, most new customers are not first-time Internet users, but... transferred customers' là hệ quả của việc thị trường bão hòa, ít người dùng mới → (B)."}]},{"ns":[176,180],"head":"Questions 176-180 refer to the following e-mails.","passages":["<p>Dear Mr. Dellucci,</p><p>Thank you for your recent order for cleaning supplies through Joyful Cleaning. We particularly hope that you get excellent results from the Lemontime Floor Cleaner, whose formula has recently been changed to make it more effective. The shipment is currently scheduled to arrive on November 24.</p><p>This order puts you into the category of \"High-Volume Customer,\" meaning that you are now eligible to join our High-Volume Customer Rewards program (HVCR). Under this program, businesses like yours pay an annual fee of $95 for a membership card. The card allows you to get five percent off all orders for a twelve-month period. You'll also be able to sign up for next-day delivery instead of our usual five-day delivery, even without advance notice. This would apply to any of your three hotel branches. You'll also be sent free samples of new products as they come out.</p><p>To sign up, please respond to this e-mail. If you do so by 5 P.M. today, you'll be able to receive your current order one day early.</p><p>Warmest regards,<br>Connie Emmerson</p>","<div class=\"hdr\"><p><b>To:</b> Joyful Cleaning &lt;c_emmerson@joyfulcleaning.com&gt;</p><p><b>From:</b> Gregorio Dellucci &lt;dellucci@kokomohotel.com&gt;</p><p><b>Date:</b> November 19, 1:48 P.M.</p><p><b>Subject:</b> RE: Account #5872-R2003</p></div><p>Dear Ms. Emmerson,</p><p>I am interested in HVCR membership, so please bill my account for the $95 membership fee. Also, for the last shipment, the delivery person left the box on the reception desk while the receptionist had stepped out, so it sat there for several minutes with no one keeping an eye on it. I hope this will not happen on the new delivery date.</p><p>Thanks!<br>Gregorio Dellucci</p>"],"vi":"Kính gửi ông Dellucci,\nCảm ơn ông đã đặt mua đồ vệ sinh qua Joyful Cleaning. Chúng tôi đặc biệt mong ông hài lòng với nước lau sàn Lemontime, sản phẩm vừa được đổi công thức để hiệu quả hơn. Hàng hiện dự kiến giao ngày 24/11.\nĐơn hàng này đưa ông vào nhóm \"Khách hàng mua số lượng lớn\", nghĩa là ông đủ điều kiện tham gia chương trình Ưu đãi Khách hàng mua số lượng lớn (HVCR). Theo chương trình, các doanh nghiệp như của ông trả phí 95 đô mỗi năm cho thẻ hội viên. Thẻ giúp giảm 5% mọi đơn hàng trong 12 tháng. Ông còn có thể đăng ký giao hàng ngày hôm sau thay vì 5 ngày như thường lệ, kể cả không báo trước. Quyền lợi này áp dụng cho cả ba chi nhánh khách sạn của ông. Ông cũng được gửi mẫu dùng thử miễn phí khi có sản phẩm mới.\nĐể đăng ký, vui lòng trả lời e-mail này. Nếu trả lời trước 5 giờ chiều hôm nay, ông sẽ nhận đơn hàng hiện tại sớm một ngày.\nTrân trọng, Connie Emmerson\n\nNgười nhận: Joyful Cleaning | Người gửi: Gregorio Dellucci | Ngày: 19/11, 1:48 chiều | Chủ đề: RE: Tài khoản #5872-R2003\nKính gửi bà Emmerson,\nTôi muốn đăng ký hội viên HVCR, vui lòng tính phí hội viên 95 đô vào tài khoản của tôi. Ngoài ra, lần giao hàng trước, nhân viên giao hàng để thùng hàng trên quầy lễ tân lúc lễ tân vừa ra ngoài, nên thùng hàng nằm đó vài phút mà không ai trông. Mong chuyện này không lặp lại vào ngày giao hàng mới.\nCảm ơn! Gregorio Dellucci","qs":[{"n":176,"q":"What is one purpose of the first e-mail?","qvi":"Một mục đích của e-mail thứ nhất là gì?","opts":["To get feedback about a service","To explain an opportunity for businesses","To promote a cleaning product","To advertise a new loyalty program"],"ans":"B","xp":"E-mail giải thích ông 'are now eligible to join our High-Volume Customer Rewards program' và các quyền lợi cho doanh nghiệp → (B). (D) không nói chương trình là mới."},{"n":177,"q":"What is NOT indicated as a benefit of HVCR?","qvi":"Điều gì KHÔNG được nêu là quyền lợi của HVCR?","opts":["Lower prices on products","Advance notice of sales","Complimentary samples","Overnight shipments"],"ans":"B","xp":"(A) 'five percent off'; (C) 'free samples'; (D) 'next-day delivery'. Không nhắc báo trước đợt giảm giá → (B)."},{"n":178,"q":"What is suggested about Mr. Dellucci?","qvi":"Có thể suy ra điều gì về ông Dellucci?","opts":["He wrote a review for Lemontime Floor Cleaner.","He wanted to add more items to his order.","He oversees more than one business location.","He paid for the express delivery of some items."],"ans":"C","xp":"'This would apply to any of your three hotel branches' → ông quản lý ba chi nhánh khách sạn → (C)."},{"n":179,"q":"When most likely will Mr. Dellucci receive his order?","qvi":"Ông Dellucci nhiều khả năng sẽ nhận hàng ngày nào?","opts":["On November 19","On November 20","On November 23","On November 24"],"ans":"C","xp":"Hàng dự kiến giao 24/11; nếu đăng ký trước 5 giờ chiều hôm nay sẽ nhận sớm một ngày. Ông trả lời lúc 1:48 chiều 19/11 và đăng ký → nhận hàng 23/11 → (C)."},{"n":180,"q":"What problem does Mr. Dellucci tell Ms. Emmerson about?","qvi":"Ông Dellucci báo vấn đề gì?","opts":["A package had the wrong items.","A package was left unattended.","He received some damaged items.","He was overcharged for delivery."],"ans":"B","xp":"'it sat there for several minutes with no one keeping an eye on it' → thùng hàng bị để không ai trông → (B)."}]},{"ns":[181,185],"head":"Questions 181-185 refer to the following letter and order form.","passages":["<p>Kimberly Shaw<br>1358 Wilmington Avenue<br>Winnipeg, MB R3G 3P4<br>Canada</p><p>February 6</p><p>Dear Ms. Shaw,</p><p>Thank you for sending in your updated photo release form, which shows that we have permission to use the photo for a limited purpose once you receive payment from us. As usual, your payment for any outstanding commissions will be issued on the 20th of this month.</p><p>I'm also pleased to inform you that Kirwan Publishing will launch several new publications in the coming months, so we will be relying on freelance photography services more than ever. We're offering a fifty percent discount on all magazines to freelancers who have contributed to any of our magazines in the past month. The discount can be obtained by using the code REF561 on the online checkout page.</p><p>I look forward to continuing working with you!</p><p>Warmest regards,<br>Calvin Leroy</p>","<h3>Your order has been processed!</h3><p><b>February Special:</b> Subscribe to three or more magazines and receive a complimentary calendar.</p><table><tr><td>Name:</td><td>José Hudson</td></tr><tr><td>E-mail Address:</td><td>jose@hudsonphotoshowcase.com</td></tr><tr><td>Order Date:</td><td>February 19</td></tr><tr><td>Payment Method:</td><td>Credit Card XXXX-XXXX-XXXX-4574</td></tr><tr><td>Billing Address:</td><td>José Hudson, 925 Bolman Court, Vancouver, BC V6J 4A1, Canada</td></tr><tr><td>Shipping Address:</td><td>same as above</td></tr></table><table><tr><th>Product Description(s)</th><td></td></tr><tr><td>Outdoor Monthly 1-year subscription</td><td>$20.00</td></tr><tr><td>Under the Stars 1-year subscription</td><td>$15.00</td></tr><tr><td>Wildlife Insider 1-year subscription</td><td>$18.00</td></tr><tr><td>Discount Code (REF561)</td><td>-$26.50</td></tr><tr><td>TOTAL DUE</td><td>$26.50</td></tr></table><p>You will receive the first issue of your subscription(s) on the 5th of the month following your order. Customers are sent paperwork to renew their subscriptions two months before the subscription expires.</p>"],"vi":"Gửi bà Kimberly Shaw, 1358 Wilmington Avenue, Winnipeg, Canada – ngày 6/2\nKính gửi bà Shaw,\nCảm ơn bà đã gửi mẫu cho phép sử dụng ảnh bản cập nhật, xác nhận chúng tôi được dùng ảnh cho mục đích giới hạn sau khi bà nhận được tiền. Như thường lệ, tiền thù lao còn nợ sẽ được trả vào ngày 20 tháng này.\nTôi cũng vui mừng thông báo Nhà xuất bản Kirwan sẽ ra mắt nhiều ấn phẩm mới trong những tháng tới, nên chúng tôi sẽ cần dịch vụ chụp ảnh tự do hơn bao giờ hết. Chúng tôi giảm 50% tất cả tạp chí cho những người làm tự do đã đóng góp cho bất kỳ tạp chí nào của chúng tôi trong tháng qua. Nhập mã REF561 ở trang thanh toán trực tuyến để được giảm giá.\nMong tiếp tục được làm việc với bà! Trân trọng, Calvin Leroy\n\nĐơn hàng của bạn đã được xử lý! Ưu đãi tháng 2: đặt từ ba tạp chí trở lên được tặng lịch.\nTên: José Hudson | E-mail: jose@hudsonphotoshowcase.com | Ngày đặt: 19/2 | Thanh toán: thẻ tín dụng ****4574 | Địa chỉ: 925 Bolman Court, Vancouver, Canada | Giao hàng: như trên\nOutdoor Monthly 1 năm 20 đô | Under the Stars 1 năm 15 đô | Wildlife Insider 1 năm 18 đô | Mã giảm giá REF561 −26,50 đô | Tổng 26,50 đô\nBạn sẽ nhận số đầu tiên vào ngày 5 của tháng sau tháng đặt hàng. Khách hàng được gửi giấy tờ gia hạn hai tháng trước khi hết hạn đăng ký.","qs":[{"n":181,"q":"Why did Mr. Leroy send the letter?","qvi":"Vì sao ông Leroy gửi thư?","opts":["To request adjustments to a photo","To offer Ms. Shaw a job","To acknowledge receipt of a form","To apologize for a delay"],"ans":"C","xp":"'Thank you for sending in your updated photo release form' → xác nhận đã nhận mẫu đơn → (C)."},{"n":182,"q":"What will be sent to Ms. Shaw later this month?","qvi":"Cuối tháng này bà Shaw sẽ được gửi gì?","opts":["A work assignment","A new magazine","A contract","A payment"],"ans":"D","xp":"'your payment for any outstanding commissions will be issued on the 20th of this month' → (D)."},{"n":183,"q":"What is true about Kirwan Publishing?","qvi":"Điều gì đúng về Nhà xuất bản Kirwan?","opts":["It will open a new photography department.","It plans to expand its product range.","It has experienced a decline in readership.","It has been nominated for an award."],"ans":"B","xp":"'Kirwan Publishing will launch several new publications in the coming months' → mở rộng sản phẩm → (B)."},{"n":184,"q":"What is implied about Mr. Hudson?","qvi":"Có thể suy ra điều gì về ông Hudson?","opts":["He provided a letter of reference for Ms. Shaw.","He recently published work through Kirwan Publishing.","He is a regular customer of Kirwan Publishing.","He is the editor of Outdoor Monthly."],"ans":"B","xp":"Ông dùng mã 'REF561', mã này chỉ dành cho 'freelancers who have contributed to any of our magazines in the past month' → ông vừa có tác phẩm đăng ở Kirwan → (B)."},{"n":185,"q":"What is suggested about Mr. Hudson's order?","qvi":"Có thể suy ra điều gì về đơn hàng của ông Hudson?","opts":["It will be automatically renewed.","It will be sent to multiple addresses.","It will include a free gift.","It will expire in about two months."],"ans":"C","xp":"Ông đặt 3 tạp chí; 'February Special: Subscribe to three or more magazines and receive a complimentary calendar' → được tặng lịch → (C)."}]},{"ns":[186,190],"head":"Questions 186-190 refer to the following e-mail, flyer, and schedule.","passages":["<div class=\"hdr\"><p><b>To:</b> Carolyn Dana &lt;dana_c@ingrameden.com&gt;</p><p><b>From:</b> Matthew Wallace &lt;wallace_m@ingrameden.com&gt;</p><p><b>Date:</b> March 8</p><p><b>Subject:</b> Cultural activities</p></div><p>Hi Carolyn,</p><p>How are you? I hope you are getting used to the differences between the Covington branch and our branch. We're glad to have you as part of the team. As you were unable to attend the most recent team leader meeting, I wanted to let you know what happened. We mainly discussed what to do for our spring team-building activity next month. Based on the feedback we've previously received from the staff, we thought that a traditional dance show would be best.</p><p>We haven't announced the date yet, as I'm still looking into our ticketing options. On the event day, everyone will work a half day in the morning, attend the show in the afternoon, and return to the office by early evening. I'll buy group tickets for non-members so that everyone can participate. It seems like our budget of five hundred dollars will cover the tickets for all staff members with a little left over for the parking fees.</p><p>I'll provide you with more details once they are finalized.</p><p>Sincerely,<br>Matthew Wallace<br>HR Team Leader, Ingram Eden</p>","<h3>Take a trip to the past with a traditional dance show at Horizon Theater!</h3><p>The Moon Bay Dance Troupe has been sharing the joy of traditional dance with audiences all over the world. Enjoy the sights and sounds of dances that have been passed down through generations. Visit our box office to reserve your tickets. Or book online to avoid the ticket handling fee.</p><p>Group rates are available no matter how you purchase your tickets.</p><table><tr><td>10 tickets:</td><td>$140</td></tr><tr><td>20 tickets:</td><td>$250</td></tr><tr><td>40 tickets:</td><td>$480</td></tr><tr><td>50 tickets:</td><td>$550</td></tr></table><p>Box office: 806 Kent Street, (649) 555-3198<br>Web site: www.htheaterboxoffice.com</p>","<h3>Horizon Theater</h3><h4>Moon Bay Dance Troupe Upcoming Shows</h4><table><tr><th>Date</th><th>Start Time</th><th>Featured Performer</th><th>Ticket Restrictions</th></tr><tr><td>April 2</td><td>8:00 P.M.</td><td>Salini Chetti</td><td>None</td></tr><tr><td>April 5</td><td>2:00 P.M.</td><td>Salini Chetti</td><td>Members only</td></tr><tr><td>April 9</td><td>8:00 P.M.</td><td>Ayush Kamal</td><td>Members only</td></tr><tr><td>April 12</td><td>2:00 P.M.</td><td>Ayush Kamal</td><td>None</td></tr></table><p>For a complete list of events at Horizon Theater, visit www.htheaterboxoffice.com.</p>"],"vi":"Người nhận: Carolyn Dana | Người gửi: Matthew Wallace | Ngày: 8/3 | Chủ đề: Hoạt động văn hóa\nChào Carolyn, chị khỏe không? Mong chị đã quen với những khác biệt giữa chi nhánh Covington và chi nhánh mình. Chúng tôi rất vui có chị trong nhóm. Vì chị không dự được buổi họp trưởng nhóm gần nhất, tôi muốn báo chị nội dung. Chủ yếu chúng tôi bàn về hoạt động gắn kết nhóm mùa xuân vào tháng sau. Dựa trên góp ý trước đây của nhân viên, chúng tôi nghĩ một buổi xem múa truyền thống là tốt nhất.\nChúng tôi chưa thông báo ngày vì tôi còn tìm hiểu các lựa chọn mua vé. Hôm đó, mọi người sẽ làm nửa ngày buổi sáng, xem biểu diễn buổi chiều và về văn phòng lúc chiều tối. Tôi sẽ mua vé đoàn cho người không phải hội viên để ai cũng tham gia được. Có vẻ ngân sách 500 đô đủ mua vé cho toàn bộ nhân viên và còn dư chút ít cho phí đỗ xe.\nKhi chốt xong chi tiết tôi sẽ báo chị. Trân trọng, Matthew Wallace – Trưởng nhóm nhân sự, Ingram Eden\n\nHãy du hành về quá khứ với buổi múa truyền thống tại nhà hát Horizon! Đoàn múa Moon Bay mang niềm vui múa truyền thống đến khán giả khắp thế giới. Thưởng thức hình ảnh và âm thanh của những điệu múa truyền qua nhiều thế hệ. Đến phòng vé để đặt vé, hoặc đặt trực tuyến để không mất phí xử lý vé. Có giá vé đoàn dù bạn mua theo cách nào: 10 vé 140 đô; 20 vé 250 đô; 40 vé 480 đô; 50 vé 550 đô. Phòng vé: 806 Kent Street, (649) 555-3198. Web: www.htheaterboxoffice.com\n\nNhà hát Horizon – Lịch diễn sắp tới của đoàn Moon Bay: 2/4, 8 giờ tối, Salini Chetti, không giới hạn | 5/4, 2 giờ chiều, Salini Chetti, chỉ hội viên | 9/4, 8 giờ tối, Ayush Kamal, chỉ hội viên | 12/4, 2 giờ chiều, Ayush Kamal, không giới hạn.","qs":[{"n":186,"q":"What is the purpose of Mr. Wallace's e-mail?","qvi":"Mục đích e-mail của ông Wallace là gì?","opts":["To request a feedback form","To reschedule a meeting","To report a decision","To schedule a job interview"],"ans":"C","xp":"Ông báo lại cho Carolyn nội dung cuộc họp: 'we thought that a traditional dance show would be best' → báo một quyết định → (C)."},{"n":187,"q":"What is suggested in the e-mail about Ms. Dana?","qvi":"E-mail gợi ý điều gì về cô Dana?","opts":["She used to work at Horizon Theater.","She recently transferred to a new branch.","She suggested attending more cultural events.","She lost some tickets to a show."],"ans":"B","xp":"'I hope you are getting used to the differences between the Covington branch and our branch. We're glad to have you as part of the team' → cô vừa chuyển từ chi nhánh khác đến → (B)."},{"n":188,"q":"What benefit of making an online booking is mentioned in the flyer?","qvi":"Tờ rơi nhắc lợi ích nào của việc đặt vé trực tuyến?","opts":["Selecting parking in advance","Having more seating options","Receiving discounts on refreshments","Avoiding a handling charge"],"ans":"D","xp":"'book online to avoid the ticket handling fee' → (D)."},{"n":189,"q":"How many people most likely work at Ingram Eden?","qvi":"Ingram Eden nhiều khả năng có bao nhiêu nhân viên?","opts":["10","20","40","50"],"ans":"C","xp":"Ngân sách 500 đô 'will cover the tickets for all staff members with a little left over'; bảng giá: 40 vé = 480 đô (dư 20 đô), 50 vé = 550 đô (vượt ngân sách) → khoảng 40 người → (C)."},{"n":190,"q":"When will Ingram Eden employees most likely attend a performance?","qvi":"Nhân viên Ingram Eden nhiều khả năng xem biểu diễn ngày nào?","opts":["April 2","April 5","April 9","April 12"],"ans":"D","xp":"E-mail: xem 'in the afternoon' và mua vé 'for non-members'; lịch: suất buổi chiều (2:00 P.M.) không giới hạn hội viên là 12/4 → (D). (B) 5/4 chỉ dành cho hội viên."}]},{"ns":[191,195],"head":"Questions 191-195 refer to the following memo, schedule, and notice.","passages":["<div class=\"hdr\"><p><b>To:</b> All Staff</p><p><b>From:</b> Natalie Lantz, Office Manager</p><p><b>Re:</b> Renovations</p><p><b>Date:</b> April 17</p></div><p>Due to renovations throughout the Perine Enterprises building beginning on May 2, the two conference rooms on the 2nd floor will be used as workspaces for employees. We understand that this is an inconvenience, but we're certain you will be able to get by with the temporary setup as necessary. Departments will use the conference rooms according to the following schedule:</p><ul><li>Week 1 (May 2-8): Sales and Marketing</li><li>Week 2 (May 9-15): Accounting</li><li>Week 3 (May 16-22): Research and Development</li><li>Week 4 (May 23-29): Human Resources</li></ul><p>In Week 5 (May 30-June 5), renovations will take place in the lobby. The main entrance will be closed during this time, so employees and visitors should use the door on the eastern side of the building.</p><p>Thank you for your cooperation.</p>","<h3>O'Malley Construction</h3><h4>Work Schedule: Perine Enterprises, May 2-June 5</h4><p>Work Order: #58305 / Contact: Natalie Lantz</p><table><tr><th>WEEK</th><th>LOCATION</th><th>TASKS</th></tr><tr><td>Week 1</td><td>4th Floor</td><td>Repaint walls, remove carpeting, install floor tiles</td></tr><tr><td>Week 2</td><td>5th Floor</td><td>Repaint walls, build cupboards at end of hallway</td></tr><tr><td>Week 3</td><td>2nd Floor</td><td>Repaint walls, window installation x 12</td></tr><tr><td>Week 4</td><td>3rd Floor</td><td>Repaint walls, fix broken floor tiles</td></tr><tr><td>Week 5</td><td>1st Floor (Lobby)</td><td>Expand entrance, install marble flooring, rewire ceiling lights</td></tr></table>","<h3>NOTICE TO PERINE ENTERPRISES STAFF</h3><p>The Saginaw Avenue entrance to our building will be closed from May 30 to June 5 as part of the renovation work. For those of you who need a security card for the Turner Street entrance, please see Security Director Li Wan. The reception area will be closed during this time, but a table will be set up near the elevators, from which the receptionists will carry out their regular duties. Please inform visitors of the change. If it is easier to see visitors at an off-site location, you may be eligible to have the expenses covered by company funds. See Eleanor Butler to get permission in advance. Questions about the progress of the renovations may be directed to Gina Lombardi.</p>"],"vi":"Gửi: Toàn thể nhân viên | Từ: Natalie Lantz, Quản lý văn phòng | V/v: Cải tạo | Ngày: 17/4\nDo tòa nhà Perine Enterprises được cải tạo toàn bộ từ ngày 2/5, hai phòng hội nghị ở tầng 2 sẽ được dùng làm chỗ làm việc cho nhân viên. Chúng tôi hiểu điều này bất tiện, nhưng tin rằng mọi người sẽ xoay xở được với chỗ làm tạm khi cần. Các phòng ban dùng phòng hội nghị theo lịch: Tuần 1 (2–8/5): Kinh doanh và Marketing; Tuần 2 (9–15/5): Kế toán; Tuần 3 (16–22/5): Nghiên cứu và Phát triển; Tuần 4 (23–29/5): Nhân sự.\nTuần 5 (30/5–5/6), sảnh sẽ được cải tạo. Lối vào chính đóng cửa trong thời gian này, nhân viên và khách nên dùng cửa phía đông tòa nhà. Cảm ơn sự hợp tác của mọi người.\n\nCông ty xây dựng O'Malley – Lịch thi công Perine Enterprises, 2/5–5/6 (Lệnh #58305, liên hệ: Natalie Lantz)\nTuần 1 – tầng 4: sơn tường, gỡ thảm, lát gạch | Tuần 2 – tầng 5: sơn tường, đóng tủ cuối hành lang | Tuần 3 – tầng 2: sơn tường, lắp 12 cửa sổ | Tuần 4 – tầng 3: sơn tường, sửa gạch lát vỡ | Tuần 5 – tầng 1 (sảnh): mở rộng lối vào, lát sàn đá cẩm thạch, đi lại dây đèn trần.\n\nTHÔNG BÁO GỬI NHÂN VIÊN PERINE ENTERPRISES\nLối vào phố Saginaw sẽ đóng từ 30/5 đến 5/6 do cải tạo. Ai cần thẻ an ninh để vào lối phố Turner, hãy gặp Giám đốc An ninh Li Wan. Khu lễ tân sẽ đóng trong thời gian này, nhưng sẽ có bàn đặt gần thang máy để lễ tân làm việc như thường. Vui lòng báo khách về thay đổi này. Nếu tiện gặp khách ở bên ngoài hơn, bạn có thể được công ty chi trả chi phí. Hãy gặp Eleanor Butler để xin phép trước. Thắc mắc về tiến độ cải tạo xin gửi Gina Lombardi.","qs":[{"n":191,"q":"In the memo, the phrase \"get by\" in paragraph 1, line 3, is closest in meaning to","qvi":"Trong bản ghi nhớ, cụm \"get by\" ở đoạn 1, dòng 3 gần nghĩa nhất với","opts":["manage","receive","approve","surpass"],"ans":"A","xp":"'get by with the temporary setup' = xoay xở được với chỗ làm tạm → (A) manage."},{"n":192,"q":"Where is the accounting department located in the Perine Enterprises Building?","qvi":"Phòng kế toán nằm ở tầng mấy của tòa nhà?","opts":["On the second floor","On the third floor","On the fourth floor","On the fifth floor"],"ans":"D","xp":"Bản ghi nhớ: Kế toán dùng phòng hội nghị tạm vào tuần 2; lịch thi công: tuần 2 sửa tầng 5 → phòng kế toán ở tầng 5 → (D)."},{"n":193,"q":"What is NOT mentioned as part of the renovation project?","qvi":"Điều gì KHÔNG được nhắc đến trong dự án cải tạo?","opts":["Repairing some flooring","Installing new windows","Laying some carpeting","Adding a storage area"],"ans":"C","xp":"(A) 'fix broken floor tiles'; (B) 'window installation x 12'; (D) 'build cupboards'. Thảm chỉ bị gỡ ('remove carpeting'), không trải thảm mới → (C)."},{"n":194,"q":"What is true about Perine Enterprises?","qvi":"Điều gì đúng về Perine Enterprises?","opts":["Its building's walls will all be repainted.","Its main entrance is on Saginaw Avenue.","Its employees requested site improvements.","Its reception services will be unavailable for a week."],"ans":"B","xp":"Bản ghi nhớ: tuần 5 (30/5–5/6) 'The main entrance will be closed'; thông báo: 'The Saginaw Avenue entrance... will be closed from May 30 to June 5' → lối vào chính ở phố Saginaw → (B). (D) sai: lễ tân vẫn làm việc ở bàn gần thang máy."},{"n":195,"q":"Why are employees advised to contact Ms. Butler?","qvi":"Vì sao nhân viên được khuyên liên hệ bà Butler?","opts":["To provide visitors' names","To get funding approval","To ask for a security pass","To be updated on a project"],"ans":"B","xp":"'you may be eligible to have the expenses covered by company funds. See Eleanor Butler to get permission in advance' → xin duyệt chi phí → (B). (C) gặp Li Wan, (D) hỏi Gina Lombardi."}]},{"ns":[196,200],"head":"Questions 196-200 refer to the following schedule, e-mail, and article.","passages":["<h3>Gaskell Creations</h3><h4>Sample Order Production Run</h4><p>Description: Skylark full-length dress</p><table><tr><th>Date</th><th>Production Plan</th></tr><tr><td>Sunday, May 12</td><td>Design finalized by Anja Rembert</td></tr><tr><td>Monday, May 13</td><td>Presentation of fabric options by Stroop Supplies; Request rush order on selected items</td></tr><tr><td>Thursday, May 16</td><td>Production of ten dresses; Quality control inspection (dimension check, zipper test, visual analysis)</td></tr><tr><td>Friday, May 17</td><td>Production of full sample</td></tr><tr><td>Saturday, May 18</td><td>Completed samples sent to Orchard Fashions</td></tr></table>","<div class=\"hdr\"><p><b>To:</b> Beth Ehmann &lt;ehmannb@orchardfashions.com&gt;</p><p><b>From:</b> Tammy Culver &lt;culvert@orchardfashions.com&gt;</p><p><b>Date:</b> May 21</p><p><b>Subject:</b> Skylark dresses</p></div><p>Dear Ms. Ehmann,</p><p>I have received the samples of Skylark full-length dresses from Gaskell Creations. Having reviewed the production costs and the high quality of the completed samples, I believe Gaskell Creations is the right choice for this project.</p><p>Last Thursday, I participated in the quality control inspection of the first ten dresses. The following morning, I met with the factory foreman to express my concerns about uneven hemlines. He made the appropriate adjustments to the cutting machines before resuming production. The problem did not occur in any of the dresses from the full sample.</p><p>I had a teleconference with Lily Zemanski this morning, during which I explained that the only issue with our potential partnership is that Gaskell Creations does not fit with our mission statement. Ms. Zemanski promised that the company would take measures next month to resolve that issue to our satisfaction. Therefore, I am pleased to say that we are able to move forward.</p><p>Tammy Culver</p>","<h3>Small-Town Factory Makes Big Corporate Connection</h3><p>August 8 — Manufacturer Gaskell Creations, located in the southern part of Clairsville, has started a partnership with its largest client in the company's history. Gaskell is now producing clothing garments for Orchard Fashions. To secure the contract, Gaskell made several training and equipment upgrades in June to bring its safety rating up.</p><p>\"We were happy to make changes to make sure this agreement went forward,\" said Lily Zemanski, Gaskell's executive director. \"The large contract means that we can earn back our investment quickly, and the change benefits our employees greatly. For the first time ever, we're turning away job applicants because we don't have room for them.\"</p>"],"vi":"Gaskell Creations – Kế hoạch sản xuất đơn hàng mẫu – Mô tả: váy dài Skylark\nCN 12/5: Anja Rembert chốt thiết kế | T2 13/5: Stroop Supplies giới thiệu các loại vải; yêu cầu đặt gấp những loại đã chọn | T5 16/5: may mười chiếc váy; kiểm tra chất lượng (đo kích thước, thử khóa kéo, kiểm tra bằng mắt) | T6 17/5: may toàn bộ mẫu | T7 18/5: gửi mẫu hoàn chỉnh cho Orchard Fashions\n\nNgười nhận: Beth Ehmann | Người gửi: Tammy Culver | Ngày: 21/5 | Chủ đề: Váy Skylark\nKính gửi bà Ehmann, tôi đã nhận các mẫu váy dài Skylark từ Gaskell Creations. Sau khi xem chi phí sản xuất và chất lượng cao của các mẫu hoàn chỉnh, tôi tin Gaskell Creations là lựa chọn đúng cho dự án này.\nThứ Năm tuần trước, tôi đã tham gia kiểm tra chất lượng mười chiếc váy đầu tiên. Sáng hôm sau, tôi gặp quản đốc nhà máy để nêu lo ngại về đường gấu váy không đều. Ông ấy đã chỉnh máy cắt trước khi tiếp tục sản xuất. Lỗi này không xuất hiện ở chiếc váy nào trong toàn bộ mẫu.\nSáng nay tôi họp qua điện thoại với Lily Zemanski, trong đó tôi giải thích vấn đề duy nhất của việc hợp tác là Gaskell Creations chưa phù hợp với tuyên bố sứ mệnh của chúng ta. Bà Zemanski hứa công ty sẽ có biện pháp vào tháng sau để giải quyết vấn đề đó cho chúng ta hài lòng. Vì vậy, tôi vui mừng thông báo chúng ta có thể tiến hành. – Tammy Culver\n\nNhà máy thị trấn nhỏ kết nối tập đoàn lớn\n8/8 — Nhà sản xuất Gaskell Creations ở phía nam Clairsville đã bắt đầu hợp tác với khách hàng lớn nhất trong lịch sử công ty. Gaskell hiện may quần áo cho Orchard Fashions. Để có hợp đồng, vào tháng 6 Gaskell đã nâng cấp đào tạo và thiết bị để nâng mức xếp hạng an toàn.\n\"Chúng tôi vui lòng thay đổi để thỏa thuận được tiến hành,\" bà Lily Zemanski, giám đốc điều hành Gaskell, nói. \"Hợp đồng lớn giúp chúng tôi nhanh chóng thu hồi vốn đầu tư, và thay đổi này mang lại lợi ích lớn cho nhân viên. Lần đầu tiên, chúng tôi phải từ chối người xin việc vì không còn chỗ.\"","qs":[{"n":196,"q":"What activity was completed on May 13?","qvi":"Ngày 13/5 đã hoàn thành việc gì?","opts":["Designs were advertised.","Presentations were assigned.","Fabrics were ordered.","Samples were shipped."],"ans":"C","xp":"Lịch ngày 13/5: 'Presentation of fabric options... Request rush order on selected items' → vải đã được đặt → (C). (D) gửi mẫu là ngày 18/5."},{"n":197,"q":"What does Ms. Culver suggest about the finished sample products?","qvi":"Bà Culver gợi ý điều gì về các mẫu hoàn chỉnh?","opts":["They are suitable for her company's needs.","Their quality may affect the selling price.","They were made by inexperienced workers.","They arrived later than originally scheduled."],"ans":"A","xp":"'Having reviewed... the high quality of the completed samples, I believe Gaskell Creations is the right choice' → mẫu đáp ứng nhu cầu công ty bà → (A)."},{"n":198,"q":"When did Ms. Culver most likely meet with a factory supervisor?","qvi":"Bà Culver nhiều khả năng gặp quản đốc nhà máy ngày nào?","opts":["May 12","May 16","May 17","May 18"],"ans":"C","xp":"E-mail: 'Last Thursday, I participated in the quality control inspection... The following morning, I met with the factory foreman'; lịch: kiểm tra chất lượng thứ Năm 16/5 → sáng hôm sau là thứ Sáu 17/5 → (C)."},{"n":199,"q":"What did Ms. Zemanski guarantee on May 21?","qvi":"Ngày 21/5 bà Zemanski cam kết điều gì?","opts":["That more workers would be hired right away","That the products could be produced on short notice","That environmentally friendly fabrics would be used","That Gaskell Creations would improve its safety rating"],"ans":"D","xp":"E-mail 21/5: bà hứa 'would take measures next month to resolve that issue'; bài báo: 'Gaskell made several training and equipment upgrades in June to bring its safety rating up' → cam kết nâng mức an toàn → (D)."},{"n":200,"q":"What does Ms. Zemanski suggest about her company?","qvi":"Bà Zemanski gợi ý điều gì về công ty mình?","opts":["There is a high demand for its jobs.","There are plans to open a new branch.","It is the largest employer in Clairsville.","It is currently seeking new investors."],"ans":"A","xp":"'For the first time ever, we're turning away job applicants because we don't have room for them' → nhiều người muốn vào làm → (A)."}]}]}};
